export const MIGRATIONS: [string,string][] = [["20260716151521_8004977e-92e2-4621-89e0-87152609a750.sql", "\n-- 1. Rollen-Enum\nCREATE TYPE public.app_role AS ENUM ('superadmin', 'kunde', 'mitarbeiter');\n\n-- 2. Profiles-Tabelle\nCREATE TABLE public.profiles (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name TEXT,\n  company TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;\nGRANT ALL ON public.profiles TO service_role;\n\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\n\n-- 3. user_roles-Tabelle\nCREATE TABLE public.user_roles (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  role public.app_role NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (user_id, role)\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated;\nGRANT ALL ON public.user_roles TO service_role;\n\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\n\n-- 4. Security definer has_role Funktion\nCREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role public.app_role)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$$;\n\n-- 5. RLS Policies profiles\nCREATE POLICY \"Users can view own profile\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update own profile\"\n  ON public.profiles FOR UPDATE\n  TO authenticated\n  USING (auth.uid() = user_id)\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can insert own profile\"\n  ON public.profiles FOR INSERT\n  TO authenticated\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Superadmins can view all profiles\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can update all profiles\"\n  ON public.profiles FOR UPDATE\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\n-- 6. RLS Policies user_roles\nCREATE POLICY \"Users can view own roles\"\n  ON public.user_roles FOR SELECT\n  TO authenticated\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Superadmins can view all roles\"\n  ON public.user_roles FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can manage all roles\"\n  ON public.user_roles FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\n-- 7. updated_at Trigger\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER update_profiles_updated_at\n  BEFORE UPDATE ON public.profiles\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- 8. handle_new_user Trigger: Profil + Default-Rolle \"kunde\"\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _requested_role public.app_role;\nBEGIN\n  -- Profil anlegen\n  INSERT INTO public.profiles (user_id, full_name, company)\n  VALUES (\n    NEW.id,\n    NEW.raw_user_meta_data->>'full_name',\n    NEW.raw_user_meta_data->>'company'\n  );\n\n  -- Rolle bestimmen: nur 'kunde' oder 'mitarbeiter' zul\u00e4ssig aus Metadaten,\n  -- sonst Default 'kunde'. 'superadmin' NIE per Self-Signup.\n  _requested_role := CASE\n    WHEN NEW.raw_user_meta_data->>'role' IN ('kunde', 'mitarbeiter')\n      THEN (NEW.raw_user_meta_data->>'role')::public.app_role\n    ELSE 'kunde'::public.app_role\n  END;\n\n  INSERT INTO public.user_roles (user_id, role)\n  VALUES (NEW.id, _requested_role);\n\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();\n"], ["20260716161915_b2987bdd-b9d8-4ce7-a9ea-3444a0dc82b7.sql", "CREATE TABLE public.clients (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_name text NOT NULL,\n  website text NOT NULL,\n  company_description text NOT NULL,\n  industry text NOT NULL,\n  contact_person text NOT NULL,\n  street text NOT NULL,\n  postal_code text NOT NULL,\n  city text NOT NULL,\n  vat_id text NOT NULL,\n  phone text NOT NULL,\n  email text NOT NULL,\n  contact_phone text,\n  contact_email text,\n  logo_url text,\n  greeting_text text NOT NULL,\n  forwarding_enabled boolean NOT NULL DEFAULT false,\n  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.clients TO authenticated;\nGRANT ALL ON public.clients TO service_role;\n\nALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can manage all clients\"\n  ON public.clients\n  FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_clients_updated_at\n  BEFORE UPDATE ON public.clients\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Storage policies for client-logos bucket (bucket created separately)\nCREATE POLICY \"Public read for client-logos\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'client-logos');\n\nCREATE POLICY \"Superadmins can upload client-logos\"\n  ON storage.objects FOR INSERT\n  TO authenticated\n  WITH CHECK (bucket_id = 'client-logos' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can update client-logos\"\n  ON storage.objects FOR UPDATE\n  TO authenticated\n  USING (bucket_id = 'client-logos' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can delete client-logos\"\n  ON storage.objects FOR DELETE\n  TO authenticated\n  USING (bucket_id = 'client-logos' AND public.has_role(auth.uid(), 'superadmin'));"], ["20260716163223_b855cb9a-6a62-4b64-8342-167239235a55.sql", "ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS is_draft boolean NOT NULL DEFAULT false;\nALTER TABLE public.clients\n  ALTER COLUMN company_name DROP NOT NULL,\n  ALTER COLUMN website DROP NOT NULL,\n  ALTER COLUMN company_description DROP NOT NULL,\n  ALTER COLUMN industry DROP NOT NULL,\n  ALTER COLUMN contact_person DROP NOT NULL,\n  ALTER COLUMN street DROP NOT NULL,\n  ALTER COLUMN postal_code DROP NOT NULL,\n  ALTER COLUMN city DROP NOT NULL,\n  ALTER COLUMN vat_id DROP NOT NULL,\n  ALTER COLUMN phone DROP NOT NULL,\n  ALTER COLUMN email DROP NOT NULL,\n  ALTER COLUMN greeting_text DROP NOT NULL;"], ["20260717074754_9dcdded5-44f3-4d47-81af-cb53d131c5d3.sql", "\nCREATE TABLE public.employees (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid,\n  first_name text,\n  last_name text,\n  personal_email text,\n  personal_phone text,\n  login_local_part text,\n  login_email text,\n  password_plain text,\n  contract_type text CHECK (contract_type IN ('vollzeit','teilzeit')),\n  start_date date,\n  salary numeric(10,2),\n  birth_date date,\n  birth_place text,\n  nationality text,\n  marital_status text,\n  iban text,\n  bic text,\n  bank_name text,\n  tax_id text,\n  social_security_number text,\n  health_insurance text,\n  is_draft boolean NOT NULL DEFAULT true,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE UNIQUE INDEX employees_login_email_active_uniq\n  ON public.employees (login_email)\n  WHERE is_draft = false AND login_email IS NOT NULL;\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.employees TO authenticated;\nGRANT ALL ON public.employees TO service_role;\n\nALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can manage all employees\"\n  ON public.employees\n  FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'::public.app_role))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'::public.app_role));\n\nCREATE TRIGGER employees_set_updated_at\n  BEFORE UPDATE ON public.employees\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n"], ["20260717084207_90fdafb6-be26-44d1-92ce-4793609443cf.sql", "\nCREATE TABLE public.assignments (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,\n  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (employee_id, client_id)\n);\n\nCREATE INDEX assignments_employee_id_idx ON public.assignments(employee_id);\nCREATE INDEX assignments_client_id_idx ON public.assignments(client_id);\n\nGRANT SELECT, INSERT, DELETE ON public.assignments TO authenticated;\nGRANT ALL ON public.assignments TO service_role;\n\nALTER TABLE public.assignments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view assignments\"\n  ON public.assignments FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can create assignments\"\n  ON public.assignments FOR INSERT\n  TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin') AND created_by = auth.uid());\n\nCREATE POLICY \"Superadmins can delete assignments\"\n  ON public.assignments FOR DELETE\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n"], ["20260717085758_e468c64e-1d03-4128-94ca-0fcc334910e9.sql", "ALTER TABLE public.clients\n  ADD COLUMN sip_phone_number text,\n  ADD COLUMN sip_server text,\n  ADD COLUMN sip_username text,\n  ADD COLUMN sip_password text;"], ["20260717162617_599bab75-de68-4318-8fa4-ed5f5f86eaae.sql", "\nCREATE TABLE public.contract_templates (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  title text NOT NULL,\n  category text,\n  monthly_salary numeric(10,2) NOT NULL DEFAULT 0,\n  content_html text NOT NULL DEFAULT '',\n  version integer NOT NULL DEFAULT 1,\n  is_active boolean NOT NULL DEFAULT true,\n  created_by uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.contract_templates TO authenticated;\nGRANT ALL ON public.contract_templates TO service_role;\n\nALTER TABLE public.contract_templates ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage contract templates\"\n  ON public.contract_templates FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER trg_contract_templates_updated_at\n  BEFORE UPDATE ON public.contract_templates\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TABLE public.company_signature (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  singleton boolean NOT NULL DEFAULT true UNIQUE,\n  signer_name text NOT NULL DEFAULT '',\n  signer_title text NOT NULL DEFAULT '',\n  signature_url text,\n  signature_source text NOT NULL DEFAULT 'generated' CHECK (signature_source IN ('generated','uploaded')),\n  signature_style text CHECK (signature_style IN ('elegant','professional','cursive','bold')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.company_signature TO authenticated;\nGRANT ALL ON public.company_signature TO service_role;\n\nALTER TABLE public.company_signature ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage company signature\"\n  ON public.company_signature FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER trg_company_signature_updated_at\n  BEFORE UPDATE ON public.company_signature\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n"], ["20260717162800_44a44d00-7cac-4859-ac1f-f482a6807971.sql", "\nCREATE POLICY \"Superadmins read contract-assets\"\n  ON storage.objects FOR SELECT TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE POLICY \"Superadmins insert contract-assets\"\n  ON storage.objects FOR INSERT TO authenticated\n  WITH CHECK (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE POLICY \"Superadmins update contract-assets\"\n  ON storage.objects FOR UPDATE TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE POLICY \"Superadmins delete contract-assets\"\n  ON storage.objects FOR DELETE TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n"], ["20260718071519_1927cca1-5117-4b8b-86a7-812db1265493.sql", "\n-- Helper: pr\u00fcft ob ein Kunde dem aktuell eingeloggten Mitarbeiter zugewiesen ist\nCREATE OR REPLACE FUNCTION public.is_client_assigned_to_me(_client_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.assignments a\n    JOIN public.employees e ON e.id = a.employee_id\n    WHERE a.client_id = _client_id\n      AND e.user_id = auth.uid()\n  )\n$$;\n\n-- Mitarbeiter darf zugewiesene Kunden lesen\nCREATE POLICY \"Employees can view assigned clients\"\nON public.clients\nFOR SELECT\nTO authenticated\nUSING (public.is_client_assigned_to_me(id));\n\n-- Mitarbeiter darf seine eigenen Assignment-Zeilen sehen\nCREATE POLICY \"Employees can view own assignments\"\nON public.assignments\nFOR SELECT\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = assignments.employee_id\n      AND e.user_id = auth.uid()\n  )\n);\n\n-- Mitarbeiter darf seinen eigenen employees-Datensatz sehen\nCREATE POLICY \"Employees can view own record\"\nON public.employees\nFOR SELECT\nTO authenticated\nUSING (user_id = auth.uid());\n"], ["20260719101735_c7311a7c-aa30-475e-9f47-8b80667257c0.sql", "ALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS sip_phone_number text,\n  ADD COLUMN IF NOT EXISTS sip_server text,\n  ADD COLUMN IF NOT EXISTS sip_username text,\n  ADD COLUMN IF NOT EXISTS sip_password text;\n\nALTER TABLE public.clients\n  DROP COLUMN IF EXISTS sip_phone_number,\n  DROP COLUMN IF EXISTS sip_server,\n  DROP COLUMN IF EXISTS sip_username,\n  DROP COLUMN IF EXISTS sip_password;"], ["20260721065610_636a78d4-0d36-4385-9f7d-2d833e775188.sql", "\n-- 1) client_phone_numbers\nCREATE TABLE public.client_phone_numbers (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  phone_number TEXT NOT NULL,\n  label TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (phone_number)\n);\nCREATE INDEX client_phone_numbers_client_idx ON public.client_phone_numbers(client_id);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.client_phone_numbers TO authenticated;\nGRANT ALL ON public.client_phone_numbers TO service_role;\n\nALTER TABLE public.client_phone_numbers ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin manages phone numbers\"\nON public.client_phone_numbers FOR ALL\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees read numbers of assigned clients\"\nON public.client_phone_numbers FOR SELECT\nTO authenticated\nUSING (public.is_client_assigned_to_me(client_id));\n\nCREATE TRIGGER trg_client_phone_numbers_updated_at\nBEFORE UPDATE ON public.client_phone_numbers\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- 2) sipgate_calls\nCREATE TABLE public.sipgate_calls (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  sipgate_call_id TEXT NOT NULL UNIQUE,\n  direction TEXT NOT NULL CHECK (direction IN ('in','out')),\n  from_number TEXT,\n  to_number TEXT,\n  client_id UUID REFERENCES public.clients(id) ON DELETE SET NULL,\n  answered_by_employee_id UUID REFERENCES public.employees(id) ON DELETE SET NULL,\n  handled_by_employee_id UUID REFERENCES public.employees(id) ON DELETE SET NULL,\n  status TEXT NOT NULL DEFAULT 'ringing' CHECK (status IN ('ringing','answered','missed','ended')),\n  caller_name TEXT,\n  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  answered_at TIMESTAMPTZ,\n  ended_at TIMESTAMPTZ,\n  raw_payload JSONB,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX sipgate_calls_client_idx ON public.sipgate_calls(client_id);\nCREATE INDEX sipgate_calls_status_idx ON public.sipgate_calls(status);\nCREATE INDEX sipgate_calls_started_at_idx ON public.sipgate_calls(started_at DESC);\n\nGRANT SELECT, UPDATE ON public.sipgate_calls TO authenticated;\nGRANT ALL ON public.sipgate_calls TO service_role;\n\nALTER TABLE public.sipgate_calls ENABLE ROW LEVEL SECURITY;\n\n-- Superadmin: full read\nCREATE POLICY \"Superadmin reads all calls\"\nON public.sipgate_calls FOR SELECT\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\n-- Employees: read calls for their assigned clients\nCREATE POLICY \"Employees read calls of assigned clients\"\nON public.sipgate_calls FOR SELECT\nTO authenticated\nUSING (\n  client_id IS NOT NULL\n  AND public.is_client_assigned_to_me(client_id)\n);\n\n-- Employees: can set themselves as handler (update only on assigned calls)\nCREATE POLICY \"Employees claim assigned calls\"\nON public.sipgate_calls FOR UPDATE\nTO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR (client_id IS NOT NULL AND public.is_client_assigned_to_me(client_id))\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR (client_id IS NOT NULL AND public.is_client_assigned_to_me(client_id))\n);\n\nCREATE TRIGGER trg_sipgate_calls_updated_at\nBEFORE UPDATE ON public.sipgate_calls\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Realtime\nALTER PUBLICATION supabase_realtime ADD TABLE public.sipgate_calls;\nALTER TABLE public.sipgate_calls REPLICA IDENTITY FULL;\n\n-- 3) employees.sipgate_user_id\nALTER TABLE public.employees ADD COLUMN IF NOT EXISTS sipgate_user_id TEXT;\nCREATE INDEX IF NOT EXISTS employees_sipgate_user_id_idx ON public.employees(sipgate_user_id);\n"], ["20260721070810_d1ace8da-e5e9-4b1b-ac53-1f22741cafdb.sql", "ALTER TABLE public.employees\n  DROP COLUMN IF EXISTS sip_phone_number,\n  DROP COLUMN IF EXISTS sip_server,\n  DROP COLUMN IF EXISTS sip_username,\n  DROP COLUMN IF EXISTS sip_password;"], ["20260721073145_aa88c7ec-7dc3-4e14-aab6-6931bcf53986.sql", "\nCREATE TYPE public.employee_contract_status AS ENUM ('pending_employee', 'pending_admin', 'completed');\n\nCREATE TABLE public.employee_contracts (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL UNIQUE REFERENCES public.employees(id) ON DELETE CASCADE,\n  template_id uuid NOT NULL REFERENCES public.contract_templates(id) ON DELETE RESTRICT,\n  status public.employee_contract_status NOT NULL DEFAULT 'pending_employee',\n  employee_signature_data_url text,\n  signed_at timestamptz,\n  admin_confirmed_at timestamptz,\n  admin_confirmed_by uuid,\n  pdf_path text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.employee_contracts TO authenticated;\nGRANT ALL ON public.employee_contracts TO service_role;\n\nALTER TABLE public.employee_contracts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage all employee contracts\"\n  ON public.employee_contracts FOR ALL\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees can view their own contract\"\n  ON public.employee_contracts FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.employees e\n      WHERE e.id = employee_contracts.employee_id AND e.user_id = auth.uid()\n    )\n  );\n\nCREATE POLICY \"Employees can update their own contract\"\n  ON public.employee_contracts FOR UPDATE\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.employees e\n      WHERE e.id = employee_contracts.employee_id AND e.user_id = auth.uid()\n    )\n    AND status = 'pending_employee'\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM public.employees e\n      WHERE e.id = employee_contracts.employee_id AND e.user_id = auth.uid()\n    )\n    AND status IN ('pending_employee', 'pending_admin')\n  );\n\nCREATE TRIGGER update_employee_contracts_updated_at\n  BEFORE UPDATE ON public.employee_contracts\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Employees need to update their own personal data during contract wizard\nCREATE POLICY \"Employees can update their own employee row\"\n  ON public.employees FOR UPDATE\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\nCREATE POLICY \"Employees can view their own employee row\"\n  ON public.employees FOR SELECT\n  USING (user_id = auth.uid());\n\n-- Storage policies for contract-assets bucket: employees can read their own PDF\nCREATE POLICY \"Employees can read their own contract PDF\"\n  ON storage.objects FOR SELECT\n  TO authenticated\n  USING (\n    bucket_id = 'contract-assets'\n    AND EXISTS (\n      SELECT 1\n      FROM public.employee_contracts ec\n      JOIN public.employees e ON e.id = ec.employee_id\n      WHERE e.user_id = auth.uid()\n        AND ec.pdf_path = storage.objects.name\n    )\n  );\n\nCREATE POLICY \"Superadmins manage contract-assets\"\n  ON storage.objects FOR ALL\n  TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (bucket_id = 'contract-assets' AND public.has_role(auth.uid(), 'superadmin'));\n"], ["20260721074705_27f6e0e8-a094-4bb9-bf58-a68cc396c534.sql", "CREATE POLICY \"Employees can read their assigned template\"\n  ON public.contract_templates\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM public.employee_contracts ec\n      JOIN public.employees e ON e.id = ec.employee_id\n      WHERE ec.template_id = contract_templates.id\n        AND e.user_id = auth.uid()\n    )\n  );"], ["20260721081413_b6f873c1-2a35-452e-a7f7-dce5508041da.sql", "\nCREATE TABLE public.call_notes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,\n  sipgate_call_id uuid REFERENCES public.sipgate_calls(id) ON DELETE SET NULL,\n  anrufer_name text,\n  anrufer_nummer text,\n  anrufer_email text,\n  anliegen text NOT NULL,\n  kategorie text,\n  prioritaet text NOT NULL DEFAULT 'normal',\n  weitergeleitet_an text,\n  rueckruf_gewuenscht boolean NOT NULL DEFAULT false,\n  rueckruf_zeit text,\n  ticket_erstellen boolean NOT NULL DEFAULT false,\n  dauer_sekunden integer NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.call_notes TO authenticated;\nGRANT ALL ON public.call_notes TO service_role;\n\nALTER TABLE public.call_notes ENABLE ROW LEVEL SECURITY;\n\n-- Owner (Mitarbeiter) darf lesen\nCREATE POLICY \"Employee reads own notes\" ON public.call_notes\nFOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n);\n\n-- Superadmin darf alles lesen\nCREATE POLICY \"Superadmin reads all notes\" ON public.call_notes\nFOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\n-- Insert: eigene employee_id UND Zuweisung auf Kunde\nCREATE POLICY \"Employee inserts own notes\" ON public.call_notes\nFOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n  AND public.is_client_assigned_to_me(call_notes.client_id)\n);\n\n-- Superadmin insert\nCREATE POLICY \"Superadmin inserts notes\" ON public.call_notes\nFOR INSERT TO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\n-- Update: eigener Mitarbeiter\nCREATE POLICY \"Employee updates own notes\" ON public.call_notes\nFOR UPDATE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Superadmin updates notes\" ON public.call_notes\nFOR UPDATE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\n-- Delete\nCREATE POLICY \"Employee deletes own notes\" ON public.call_notes\nFOR DELETE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Superadmin deletes notes\" ON public.call_notes\nFOR DELETE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_call_notes_updated_at\nBEFORE UPDATE ON public.call_notes\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE INDEX call_notes_employee_created_idx ON public.call_notes (employee_id, created_at DESC);\nCREATE INDEX call_notes_client_idx ON public.call_notes (client_id);\n"], ["20260721135449_ec21c6e2-b3fd-4982-9978-6c2d3bb33e0d.sql", "ALTER TABLE public.call_notes DROP COLUMN IF EXISTS ticket_erstellen;"], ["20260721155221_a39281aa-1438-4c45-899b-3d0bd05e6482.sql", "CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA extensions;\nCREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;"], ["20260721185012_338108ab-bdf6-4c23-b613-9b357002f051.sql", "CREATE TABLE public.caller_contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  phone_number text NOT NULL,\n  caller_name text,\n  caller_email text,\n  last_seen_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (client_id, phone_number)\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.caller_contacts TO authenticated;\nGRANT ALL ON public.caller_contacts TO service_role;\n\nALTER TABLE public.caller_contacts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins full access to caller_contacts\"\nON public.caller_contacts FOR ALL\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Mitarbeiter can view assigned caller_contacts\"\nON public.caller_contacts FOR SELECT\nTO authenticated\nUSING (public.is_client_assigned_to_me(client_id));\n\nCREATE POLICY \"Mitarbeiter can insert assigned caller_contacts\"\nON public.caller_contacts FOR INSERT\nTO authenticated\nWITH CHECK (public.is_client_assigned_to_me(client_id));\n\nCREATE POLICY \"Mitarbeiter can update assigned caller_contacts\"\nON public.caller_contacts FOR UPDATE\nTO authenticated\nUSING (public.is_client_assigned_to_me(client_id))\nWITH CHECK (public.is_client_assigned_to_me(client_id));\n\nCREATE INDEX idx_caller_contacts_lookup ON public.caller_contacts(client_id, phone_number);\n\nCREATE TRIGGER update_caller_contacts_updated_at\nBEFORE UPDATE ON public.caller_contacts\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();"], ["20260721202603_0cb74953-5ca9-4cac-a65c-960f7634534c.sql", "DELETE FROM public.sipgate_calls;"], ["20260722100137_f5e8d563-6e60-41eb-88ee-8c7a2da65579.sql", "\nCREATE TABLE public.applications (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  vorname TEXT NOT NULL,\n  nachname TEXT NOT NULL,\n  email TEXT NOT NULL,\n  handynummer TEXT NOT NULL,\n  geburtsdatum DATE NOT NULL,\n  staatsangehoerigkeit TEXT NOT NULL,\n  anstellung TEXT NOT NULL,\n  lebenslauf_path TEXT,\n  lebenslauf_filename TEXT,\n  lebenslauf_mime TEXT,\n  status TEXT NOT NULL DEFAULT 'neu',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, UPDATE, DELETE ON public.applications TO authenticated;\nGRANT ALL ON public.applications TO service_role;\n\nALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin can view applications\"\n  ON public.applications FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can update applications\"\n  ON public.applications FOR UPDATE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can delete applications\"\n  ON public.applications FOR DELETE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_applications_updated_at\n  BEFORE UPDATE ON public.applications\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nALTER PUBLICATION supabase_realtime ADD TABLE public.applications;\n\n-- Storage policies for applications bucket (bucket created via storage_create_bucket tool)\nCREATE POLICY \"Superadmin can read application files\"\n  ON storage.objects FOR SELECT TO authenticated\n  USING (bucket_id = 'applications' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can delete application files\"\n  ON storage.objects FOR DELETE TO authenticated\n  USING (bucket_id = 'applications' AND public.has_role(auth.uid(), 'superadmin'));\n"], ["20260722132649_fb338d6b-b16b-4fd0-96ac-eaebe9547b2c.sql", "\nCREATE TABLE public.app_settings (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  singleton boolean NOT NULL DEFAULT true UNIQUE,\n  company_name text,\n  company_address text,\n  vat_id text,\n  accent_color text DEFAULT '#7bed9f',\n  logo_text text DEFAULT 'Sekreteriat24',\n  resend_api_key text,\n  resend_from_name text,\n  resend_from_email text,\n  application_email_enabled boolean NOT NULL DEFAULT false,\n  application_email_subject text DEFAULT 'Deine Bewerbung bei Sekreteriat24',\n  application_email_body text DEFAULT 'Hallo {{vorname}},\n\nvielen Dank f\u00fcr deine Bewerbung. Wir haben deine Unterlagen erhalten und melden uns in K\u00fcrze.\n\nViele Gr\u00fc\u00dfe\nSekreteriat24',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE ON public.app_settings TO authenticated;\nGRANT ALL ON public.app_settings TO service_role;\n\nALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin can read settings\" ON public.app_settings\n  FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can insert settings\" ON public.app_settings\n  FOR INSERT TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can update settings\" ON public.app_settings\n  FOR UPDATE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_app_settings_updated_at\n  BEFORE UPDATE ON public.app_settings\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nINSERT INTO public.app_settings (singleton, company_name, company_address, vat_id)\nVALUES (true, 'Sekreteriat24 GmbH', 'Musterstra\u00dfe 12, 10115 Berlin', 'DE123456789')\nON CONFLICT (singleton) DO NOTHING;\n"], ["20260722134023_6f311249-5674-40c5-aaba-2def203341a6.sql", "ALTER TABLE public.app_settings\n  ALTER COLUMN application_email_body SET DEFAULT E'Hallo {{vorname}} {{nachname}},\\n\\nvielen Dank f\u00fcr deine Bewerbung bei Sekreteriat24.\\n\\nWir haben deine Unterlagen erhalten und pr\u00fcfen sie sorgf\u00e4ltig. In K\u00fcrze melden wir uns pers\u00f6nlich bei dir zur\u00fcck.\\n\\nMit freundlichen Gr\u00fc\u00dfen\\nDein Team von Sekreteriat24';\n\nUPDATE public.app_settings\nSET application_email_body = E'Hallo {{vorname}} {{nachname}},\\n\\nvielen Dank f\u00fcr deine Bewerbung bei Sekreteriat24.\\n\\nWir haben deine Unterlagen erhalten und pr\u00fcfen sie sorgf\u00e4ltig. In K\u00fcrze melden wir uns pers\u00f6nlich bei dir zur\u00fcck.\\n\\nMit freundlichen Gr\u00fc\u00dfen\\nDein Team von Sekreteriat24'\nWHERE application_email_body IS NULL\n   OR application_email_body ILIKE '%vielen Dank f\u00fcr deine Bewerbung. Wir haben deine Unterlagen erhalten und melden uns in K\u00fcrze.%';\n"], ["20260723073541_50bd3833-fc1e-4bf1-a4ea-21c34c913df4.sql", "-- Korrigiere bereits vorhandene Einstellungen (auch wenn Nutzer sie nicht angepasst haben)\nUPDATE public.app_settings\nSET\n  company_name = REPLACE(company_name, 'Sekreteriat', 'Sekretariat'),\n  logo_text = REPLACE(logo_text, 'Sekreteriat', 'Sekretariat'),\n  application_email_subject = REPLACE(application_email_subject, 'Sekreteriat', 'Sekretariat'),\n  application_email_body = REPLACE(application_email_body, 'Sekreteriat', 'Sekretariat');\n\n-- Setze korrigierte Default-Werte f\u00fcr zuk\u00fcnftige Zeilen\nALTER TABLE public.app_settings\n  ALTER COLUMN logo_text SET DEFAULT 'Sekretariat24',\n  ALTER COLUMN application_email_subject SET DEFAULT 'Deine Bewerbung bei Sekretariat24',\n  ALTER COLUMN application_email_body SET DEFAULT 'Hallo {{vorname}},\n\nvielen Dank f\u00fcr deine Bewerbung. Wir haben deine Unterlagen erhalten und melden uns in K\u00fcrze.\n\nViele Gr\u00fc\u00dfe\nSekretariat24';"], ["20260723094351_8ce37473-3f35-44dc-a2f9-4d0896f37d2e.sql", "ALTER TABLE public.applications ADD COLUMN IF NOT EXISTS ranking text;"], ["20260723122036_7c14a5c9-616d-46cc-a214-b1b42c67b130.sql", "\n-- 1. applications: booking_token\nALTER TABLE public.applications\n  ADD COLUMN IF NOT EXISTS booking_token uuid UNIQUE;\n\n-- 2. app_settings: interview email + slot config\nALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS interview_email_enabled boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS interview_email_subject text DEFAULT 'Buche dein Bewerbungsgespr\u00e4ch bei Sekretariat24',\n  ADD COLUMN IF NOT EXISTS interview_email_body text DEFAULT E'Hallo {{vorname}},\\n\\nwir freuen uns \u00fcber deine Bewerbung und w\u00fcrden dich gerne pers\u00f6nlich kennenlernen.\\n\\nBitte w\u00e4hle \u00fcber den folgenden Link einen f\u00fcr dich passenden Termin f\u00fcr dein Bewerbungsgespr\u00e4ch:\\n\\n{{booking_url}}\\n\\nWir freuen uns auf das Gespr\u00e4ch!\\n\\nViele Gr\u00fc\u00dfe\\nDein Sekretariat24-Team',\n  ADD COLUMN IF NOT EXISTS interview_slot_start time NOT NULL DEFAULT '09:00',\n  ADD COLUMN IF NOT EXISTS interview_slot_end time NOT NULL DEFAULT '18:00',\n  ADD COLUMN IF NOT EXISTS interview_slot_interval_minutes int NOT NULL DEFAULT 30,\n  ADD COLUMN IF NOT EXISTS interview_available_weekdays int[] NOT NULL DEFAULT ARRAY[1,2,3,4,5];\n\n-- 3. interview_appointments table\nCREATE TABLE IF NOT EXISTS public.interview_appointments (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  application_id uuid NOT NULL UNIQUE REFERENCES public.applications(id) ON DELETE CASCADE,\n  appointment_date date NOT NULL,\n  appointment_time time NOT NULL,\n  status text NOT NULL DEFAULT 'neu',\n  notes text,\n  booked_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_interview_appointments_date\n  ON public.interview_appointments (appointment_date, appointment_time);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.interview_appointments TO authenticated;\nGRANT ALL ON public.interview_appointments TO service_role;\n\nALTER TABLE public.interview_appointments ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \"Superadmins manage interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Superadmins manage interview appointments\"\n  ON public.interview_appointments\n  FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nDROP TRIGGER IF EXISTS interview_appointments_updated_at ON public.interview_appointments;\nCREATE TRIGGER interview_appointments_updated_at\n  BEFORE UPDATE ON public.interview_appointments\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- 4. RPCs for public booking (SECURITY DEFINER, token-based)\n\n-- Get applicant info by booking token (no PII leak: only first/last name + existing appointment)\nCREATE OR REPLACE FUNCTION public.get_interview_by_token(_token uuid)\nRETURNS TABLE (\n  application_id uuid,\n  vorname text,\n  nachname text,\n  appointment_date date,\n  appointment_time time,\n  status text\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT a.id, a.vorname, a.nachname,\n         ia.appointment_date, ia.appointment_time, ia.status\n  FROM public.applications a\n  LEFT JOIN public.interview_appointments ia ON ia.application_id = a.id\n  WHERE a.booking_token = _token\n  LIMIT 1;\n$$;\n\n-- Public list of booked date/time slots (no PII)\nCREATE OR REPLACE FUNCTION public.list_booked_interview_slots()\nRETURNS TABLE (appointment_date date, appointment_time time)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT appointment_date, appointment_time\n  FROM public.interview_appointments\n  WHERE appointment_date >= CURRENT_DATE;\n$$;\n\n-- Book/rebook slot via token\nCREATE OR REPLACE FUNCTION public.book_interview_slot(\n  _token uuid,\n  _date date,\n  _time time\n) RETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _app_id uuid;\n  _appt_id uuid;\nBEGIN\n  SELECT id INTO _app_id FROM public.applications WHERE booking_token = _token;\n  IF _app_id IS NULL THEN\n    RAISE EXCEPTION 'invalid_token';\n  END IF;\n\n  IF _date < CURRENT_DATE THEN\n    RAISE EXCEPTION 'past_date';\n  END IF;\n\n  -- Slot already taken by another application?\n  IF EXISTS (\n    SELECT 1 FROM public.interview_appointments\n    WHERE appointment_date = _date\n      AND appointment_time = _time\n      AND application_id <> _app_id\n  ) THEN\n    RAISE EXCEPTION 'slot_taken';\n  END IF;\n\n  INSERT INTO public.interview_appointments (application_id, appointment_date, appointment_time, status, booked_at)\n  VALUES (_app_id, _date, _time, 'neu', now())\n  ON CONFLICT (application_id) DO UPDATE\n    SET appointment_date = EXCLUDED.appointment_date,\n        appointment_time = EXCLUDED.appointment_time,\n        status = 'neu',\n        booked_at = now(),\n        updated_at = now()\n  RETURNING id INTO _appt_id;\n\n  UPDATE public.applications\n    SET status = 'termin_gebucht', updated_at = now()\n    WHERE id = _app_id;\n\n  RETURN _appt_id;\nEND;\n$$;\n\n-- Slot config for public page\nCREATE OR REPLACE FUNCTION public.get_interview_slot_config()\nRETURNS TABLE (\n  slot_start time,\n  slot_end time,\n  interval_minutes int,\n  weekdays int[],\n  company_name text,\n  accent_color text,\n  logo_text text\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT interview_slot_start, interview_slot_end, interview_slot_interval_minutes,\n         interview_available_weekdays, company_name, accent_color, logo_text\n  FROM public.app_settings\n  LIMIT 1;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_interview_by_token(uuid) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.list_booked_interview_slots() FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.book_interview_slot(uuid, date, time) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.get_interview_slot_config() FROM PUBLIC;\n\nGRANT EXECUTE ON FUNCTION public.get_interview_by_token(uuid) TO anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.list_booked_interview_slots() TO anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.book_interview_slot(uuid, date, time) TO anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.get_interview_slot_config() TO anon, authenticated;\n"], ["20260727085941_d40e0596-fd86-4296-be1a-b201d2a7286f.sql", "CREATE TABLE public.telegram_recipients (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  chat_id text NOT NULL UNIQUE,\n  label text,\n  is_active boolean NOT NULL DEFAULT true,\n  notify_applications boolean NOT NULL DEFAULT true,\n  notify_interviews boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.telegram_recipients TO authenticated;\nGRANT ALL ON public.telegram_recipients TO service_role;\n\nALTER TABLE public.telegram_recipients ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view telegram recipients\"\n  ON public.telegram_recipients FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can insert telegram recipients\"\n  ON public.telegram_recipients FOR INSERT TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can update telegram recipients\"\n  ON public.telegram_recipients FOR UPDATE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can delete telegram recipients\"\n  ON public.telegram_recipients FOR DELETE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_telegram_recipients_updated_at\n  BEFORE UPDATE ON public.telegram_recipients\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();"], ["20260727092313_b93f8df2-26e0-4701-908f-d6f97b52de48.sql", "CREATE TABLE public.activity_log (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  actor_user_id uuid NOT NULL,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text NOT NULL,\n  entity_id uuid,\n  details jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT ON public.activity_log TO authenticated;\nGRANT ALL ON public.activity_log TO service_role;\n\nALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view activity log\"\nON public.activity_log FOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can insert activity log\"\nON public.activity_log FOR INSERT TO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin') AND actor_user_id = auth.uid());\n\nCREATE INDEX activity_log_created_at_idx ON public.activity_log (created_at DESC);"], ["20260727094029_df5aea17-bceb-472b-8d8c-abd6de0f6d30.sql", "ALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS confirmation_email_enabled boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS confirmation_email_subject text,\n  ADD COLUMN IF NOT EXISTS confirmation_email_body text;\n\nUPDATE public.app_settings\nSET confirmation_email_subject = COALESCE(confirmation_email_subject, 'Ihr Termin bei Sekretariat24 ist best\u00e4tigt'),\n    confirmation_email_body = COALESCE(confirmation_email_body,\n'Sehr geehrte/r {{voller_name}},\n\nvielen Dank f\u00fcr die Buchung Ihres Bewerbungsgespr\u00e4chs. Wir freuen uns sehr auf das pers\u00f6nliche Kennenlernen.\n\nIhr Termin ist hiermit verbindlich best\u00e4tigt. Sollten Sie den Termin nicht wahrnehmen k\u00f6nnen, geben Sie uns bitte rechtzeitig Bescheid.\n\nMit freundlichen Gr\u00fc\u00dfen\nIhr Team von Sekretariat24');"], ["20260727095351_b476e867-e993-4a8b-9de1-0c79b2206b31.sql", "ALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'manager';"], ["20260727095414_1f196d78-f706-4b5a-bd92-6257498a9b93.sql", "CREATE TABLE public.managers (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL UNIQUE,\n  email text NOT NULL,\n  display_name text,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.managers TO authenticated;\nGRANT ALL ON public.managers TO service_role;\n\nALTER TABLE public.managers ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view managers\" ON public.managers\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'superadmin'));\nCREATE POLICY \"Superadmins can insert managers\" ON public.managers\nFOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\nCREATE POLICY \"Superadmins can update managers\" ON public.managers\nFOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\nCREATE POLICY \"Superadmins can delete managers\" ON public.managers\nFOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_managers_updated_at\nBEFORE UPDATE ON public.managers\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Manager-Zugriff auf den Bewerbungsgespr\u00e4ch-Arbeitsbereich\nCREATE POLICY \"Managers can view interview appointments\" ON public.interview_appointments\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can update interview appointments\" ON public.interview_appointments\nFOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can delete interview appointments\" ON public.interview_appointments\nFOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view applications\" ON public.applications\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can update applications\" ON public.applications\nFOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view activity log\" ON public.activity_log\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can insert activity log\" ON public.activity_log\nFOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'manager') AND actor_user_id = auth.uid());\n\nCREATE POLICY \"Managers can view app settings\" ON public.app_settings\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can read application files\" ON storage.objects\nFOR SELECT TO authenticated USING (bucket_id = 'applications' AND public.has_role(auth.uid(), 'manager'));\n\n-- Manager-Rolle darf nie per Self-Signup gesetzt werden (Default bleibt 'kunde')\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  _requested_role public.app_role;\nBEGIN\n  INSERT INTO public.profiles (user_id, full_name, company)\n  VALUES (\n    NEW.id,\n    NEW.raw_user_meta_data->>'full_name',\n    NEW.raw_user_meta_data->>'company'\n  );\n\n  _requested_role := CASE\n    WHEN NEW.raw_user_meta_data->>'role' IN ('kunde', 'mitarbeiter')\n      THEN (NEW.raw_user_meta_data->>'role')::public.app_role\n    ELSE 'kunde'::public.app_role\n  END;\n\n  INSERT INTO public.user_roles (user_id, role)\n  VALUES (NEW.id, _requested_role);\n\n  RETURN NEW;\nEND;\n$function$;"], ["20260728124607_71e188a0-8217-49e2-b746-4ff6f1a34c3a.sql", "ALTER TABLE public.interview_appointments ADD COLUMN IF NOT EXISTS reminder_sent_at timestamptz;"], ["20260730160741_5b19dbc3-7213-4e97-901f-3111288305f3.sql", "ALTER TABLE public.interview_appointments\n  ADD COLUMN IF NOT EXISTS start_date date,\n  ADD COLUMN IF NOT EXISTS start_asap boolean NOT NULL DEFAULT false;"], ["20260801130319_d3c300a8-0625-4776-bbd5-461b60dd3806.sql", "ALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS outbound_recruitment boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS caller_api_key text;\n\nALTER TABLE public.clients\n  ADD COLUMN IF NOT EXISTS is_recruitment boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS call_script_path text;"], ["20260801130940_2d868e8c-81ed-488f-8692-46fb578631ea.sql", "CREATE POLICY \"Superadmin manages call scripts\"\nON storage.objects FOR ALL TO authenticated\nUSING (bucket_id = 'call-scripts' AND public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (bucket_id = 'call-scripts' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees read assigned call scripts\"\nON storage.objects FOR SELECT TO authenticated\nUSING (\n  bucket_id = 'call-scripts'\n  AND EXISTS (\n    SELECT 1 FROM public.clients c\n    WHERE c.call_script_path = storage.objects.name\n      AND public.is_client_assigned_to_me(c.id)\n  )\n);"], ["20260801135552_b9ac86a4-1e9b-4e08-a542-bbb006c0047c.sql", "ALTER TABLE public.call_notes REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.call_notes;"], ["20260802081648_c015c318-07e1-477e-a01e-ee623a1d5dd7.sql", "ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS call_script_content text;"], ["20260802083737_3764dd04-491c-439f-8ac5-f261d706c948.sql", "ALTER TABLE public.clients\n  ADD COLUMN IF NOT EXISTS call_script_my_name text,\n  ADD COLUMN IF NOT EXISTS call_script_company_name text;"], ["20260803074248_337b7c93-874c-4be7-99f5-246c4ef69265.sql", "ALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS street text,\n  ADD COLUMN IF NOT EXISTS postal_code text,\n  ADD COLUMN IF NOT EXISTS city text;"], ["20260803074617_5686ed86-db13-4562-bc32-e8ffc40a5b19.sql", "ALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS welcome_email_enabled boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS welcome_email_subject text,\n  ADD COLUMN IF NOT EXISTS welcome_email_body text;\n\nUPDATE public.app_settings\nSET welcome_email_subject = COALESCE(welcome_email_subject, 'Deine Zugangsdaten f\u00fcr dein Mitarbeiterkonto'),\n    welcome_email_body = COALESCE(welcome_email_body, 'Hallo {{ vorname }},\n\nwillkommen im Team! Wir haben dein pers\u00f6nliches Mitarbeiterkonto f\u00fcr dich angelegt.\n\nUnten findest du deine Zugangsdaten. Bitte logge dich \u00fcber den Button ein und f\u00fclle im Anschluss deinen Arbeitsvertrag aus und unterschreibe ihn digital.\n\nBitte bewahre deine Zugangsdaten sicher auf und gib sie nicht an Dritte weiter.\n\nBei Fragen kannst du dich jederzeit bei uns melden.');\n"], ["20260803080251_4b71ee12-9d5f-4520-bb9a-3e29718ccbb7.sql", "ALTER TABLE public.telegram_recipients ADD COLUMN IF NOT EXISTS notify_contracts boolean NOT NULL DEFAULT true;"], ["20260804065054_1bff856f-9ed2-47c1-a2fc-87f7e9c99439.sql", "ALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS onboarding_enabled boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS phone_system text,\n  ADD COLUMN IF NOT EXISTS softphone_email text,\n  ADD COLUMN IF NOT EXISTS softphone_password text;\n\nALTER TABLE public.employees\n  DROP CONSTRAINT IF EXISTS employees_phone_system_check;\n\nALTER TABLE public.employees\n  ADD CONSTRAINT employees_phone_system_check\n  CHECK (phone_system IS NULL OR phone_system IN ('sipgate','placetel'));"], ["20260804075939_cd0002e5-9dcf-43b2-bf9c-05c531e33914.sql", "ALTER TABLE public.applications ADD COLUMN IF NOT EXISTS stelle text;"], ["20260805094822_ca783e57-9919-420a-b00c-554c0e986972.sql", "CREATE TABLE public.interview_blocked_slots (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  blocked_date date NOT NULL,\n  blocked_time time without time zone NOT NULL,\n  reason text,\n  created_by uuid,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE (blocked_date, blocked_time)\n);\n\nGRANT SELECT, INSERT, DELETE ON public.interview_blocked_slots TO authenticated;\nGRANT ALL ON public.interview_blocked_slots TO service_role;\n\nALTER TABLE public.interview_blocked_slots ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view blocked slots\"\n  ON public.interview_blocked_slots FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can create blocked slots\"\n  ON public.interview_blocked_slots FOR INSERT TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can delete blocked slots\"\n  ON public.interview_blocked_slots FOR DELETE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE OR REPLACE FUNCTION public.list_booked_interview_slots()\nRETURNS TABLE(appointment_date date, appointment_time time without time zone)\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\n  SELECT appointment_date, appointment_time\n  FROM public.interview_appointments\n  WHERE appointment_date >= CURRENT_DATE\n  UNION\n  SELECT blocked_date, blocked_time\n  FROM public.interview_blocked_slots\n  WHERE blocked_date >= CURRENT_DATE;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.book_interview_slot(_token uuid, _date date, _time time without time zone)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  _app_id uuid;\n  _appt_id uuid;\nBEGIN\n  SELECT id INTO _app_id FROM public.applications WHERE booking_token = _token;\n  IF _app_id IS NULL THEN\n    RAISE EXCEPTION 'invalid_token';\n  END IF;\n\n  IF _date < CURRENT_DATE THEN\n    RAISE EXCEPTION 'past_date';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.interview_blocked_slots\n    WHERE blocked_date = _date AND blocked_time = _time\n  ) THEN\n    RAISE EXCEPTION 'slot_blocked';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.interview_appointments\n    WHERE appointment_date = _date\n      AND appointment_time = _time\n      AND application_id <> _app_id\n  ) THEN\n    RAISE EXCEPTION 'slot_taken';\n  END IF;\n\n  INSERT INTO public.interview_appointments (application_id, appointment_date, appointment_time, status, booked_at)\n  VALUES (_app_id, _date, _time, 'neu', now())\n  ON CONFLICT (application_id) DO UPDATE\n    SET appointment_date = EXCLUDED.appointment_date,\n        appointment_time = EXCLUDED.appointment_time,\n        status = 'neu',\n        booked_at = now(),\n        updated_at = now()\n  RETURNING id INTO _appt_id;\n\n  UPDATE public.applications\n    SET status = 'termin_gebucht', updated_at = now()\n    WHERE id = _app_id;\n\n  RETURN _appt_id;\nEND;\n$function$;"], ["20260805125445_3b259428-0f17-4534-ba0f-bbd463e89591.sql", "\n-- Conversations: one per employee\nCREATE TABLE public.chat_conversations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL UNIQUE REFERENCES public.employees(id) ON DELETE CASCADE,\n  last_message_at timestamptz,\n  employee_active_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_conversations TO authenticated;\nGRANT ALL ON public.chat_conversations TO service_role;\n\nALTER TABLE public.chat_conversations ENABLE ROW LEVEL SECURITY;\n\n-- Helper: is this conversation mine (as employee)?\nCREATE OR REPLACE FUNCTION public.is_my_conversation(_conversation_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.chat_conversations c\n    JOIN public.employees e ON e.id = c.employee_id\n    WHERE c.id = _conversation_id\n      AND e.user_id = auth.uid()\n  )\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_my_employee_row(_employee_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = _employee_id AND e.user_id = auth.uid()\n  )\n$$;\n\nCREATE POLICY \"Staff can view own conversation\"\nON public.chat_conversations FOR SELECT TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n);\n\nCREATE POLICY \"Staff can create own conversation\"\nON public.chat_conversations FOR INSERT TO authenticated\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n);\n\nCREATE POLICY \"Staff can update own conversation\"\nON public.chat_conversations FOR UPDATE TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n);\n\nCREATE POLICY \"Admins can delete conversations\"\nON public.chat_conversations FOR DELETE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\n-- Messages\nCREATE TABLE public.chat_messages (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  conversation_id uuid NOT NULL REFERENCES public.chat_conversations(id) ON DELETE CASCADE,\n  sender_role text NOT NULL CHECK (sender_role IN ('manager','mitarbeiter')),\n  sender_user_id uuid,\n  sent_as_superadmin boolean NOT NULL DEFAULT false,\n  content text NOT NULL DEFAULT '',\n  edited_at timestamptz,\n  deleted_at timestamptz,\n  read boolean NOT NULL DEFAULT false,\n  read_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX idx_chat_messages_conversation ON public.chat_messages(conversation_id, created_at);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_messages TO authenticated;\nGRANT ALL ON public.chat_messages TO service_role;\n\nALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Participants can view messages\"\nON public.chat_messages FOR SELECT TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_conversation(conversation_id)\n);\n\nCREATE POLICY \"Participants can send messages\"\nON public.chat_messages FOR INSERT TO authenticated\nWITH CHECK (\n  (\n    (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'))\n    AND sender_role = 'manager'\n  )\n  OR (\n    public.is_my_conversation(conversation_id)\n    AND sender_role = 'mitarbeiter'\n    AND sender_user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Participants can update messages\"\nON public.chat_messages FOR UPDATE TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_conversation(conversation_id)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_conversation(conversation_id)\n);\n\nCREATE POLICY \"Admins can delete messages\"\nON public.chat_messages FOR DELETE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\n-- Agent settings (singleton)\nCREATE TABLE public.chat_agent_settings (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  singleton boolean NOT NULL DEFAULT true UNIQUE,\n  display_name text NOT NULL DEFAULT 'Daniel Schreiber',\n  status text NOT NULL DEFAULT 'online' CHECK (status IN ('online','away','offline')),\n  status_text text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE ON public.chat_agent_settings TO authenticated;\nGRANT ALL ON public.chat_agent_settings TO service_role;\n\nALTER TABLE public.chat_agent_settings ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Authenticated can read agent settings\"\nON public.chat_agent_settings FOR SELECT TO authenticated\nUSING (true);\n\nCREATE POLICY \"Admins can insert agent settings\"\nON public.chat_agent_settings FOR INSERT TO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Admins can update agent settings\"\nON public.chat_agent_settings FOR UPDATE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'));\n\nINSERT INTO public.chat_agent_settings (singleton) VALUES (true);\n\n-- updated_at triggers\nCREATE TRIGGER trg_chat_conversations_updated_at\nBEFORE UPDATE ON public.chat_conversations\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER trg_chat_messages_updated_at\nBEFORE UPDATE ON public.chat_messages\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER trg_chat_agent_settings_updated_at\nBEFORE UPDATE ON public.chat_agent_settings\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- keep last_message_at in sync\nCREATE OR REPLACE FUNCTION public.chat_touch_conversation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  UPDATE public.chat_conversations\n    SET last_message_at = NEW.created_at, updated_at = now()\n    WHERE id = NEW.conversation_id;\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER trg_chat_messages_touch\nAFTER INSERT ON public.chat_messages\nFOR EACH ROW EXECUTE FUNCTION public.chat_touch_conversation();\n\n-- realtime\nALTER TABLE public.chat_messages REPLICA IDENTITY FULL;\nALTER TABLE public.chat_conversations REPLICA IDENTITY FULL;\nALTER TABLE public.chat_agent_settings REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_messages;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_conversations;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_agent_settings;\n"], ["20260805130222_f962f6e3-724a-4059-a5f6-3ab990211f8a.sql", "ALTER TABLE public.chat_agent_settings\n  DROP COLUMN IF EXISTS status_text,\n  ADD COLUMN IF NOT EXISTS online_from time NOT NULL DEFAULT '09:00',\n  ADD COLUMN IF NOT EXISTS offline_after time NOT NULL DEFAULT '18:00',\n  ADD COLUMN IF NOT EXISTS auto_offline boolean NOT NULL DEFAULT true;"], ["20260805131841_4699dbd2-cd32-472c-904e-ce317b61e03d.sql", "ALTER TABLE public.telegram_recipients\n  ADD COLUMN IF NOT EXISTS notify_chat boolean NOT NULL DEFAULT false;"], ["20260809071757_829f9d7e-4867-4446-9e84-6ff194329589.sql", "CREATE TABLE public.onboarding_appointments (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  application_id uuid REFERENCES public.applications(id) ON DELETE SET NULL,\n  vorname text,\n  nachname text,\n  email text,\n  telefon text,\n  stelle text,\n  appointment_date date NOT NULL,\n  appointment_time time without time zone NOT NULL,\n  notes text,\n  status text NOT NULL DEFAULT 'offen',\n  reminder_sent_at timestamp with time zone,\n  created_by uuid,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.onboarding_appointments TO authenticated;\nGRANT ALL ON public.onboarding_appointments TO service_role;\n\nALTER TABLE public.onboarding_appointments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage onboarding appointments\"\nON public.onboarding_appointments FOR ALL TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_onboarding_appointments_updated_at\nBEFORE UPDATE ON public.onboarding_appointments\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE INDEX idx_onboarding_appointments_date ON public.onboarding_appointments (appointment_date);\n\nALTER TABLE public.telegram_recipients\n  ADD COLUMN IF NOT EXISTS notify_onboarding boolean NOT NULL DEFAULT true;"], ["20260809072616_0ec30e97-3d7c-4eb2-ba6d-07686157719e.sql", "ALTER TABLE public.onboarding_appointments ADD COLUMN IF NOT EXISTS start_date date;"], ["20260810121312_416f20f7-2265-4adf-b4da-b73a98cc3d2c.sql", "CREATE POLICY \"Managers manage onboarding appointments\"\nON public.onboarding_appointments FOR ALL TO authenticated\nUSING (public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view employees\"\nON public.employees FOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view employee contracts\"\nON public.employee_contracts FOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'manager'));"], ["20260810122003_2753e957-1dd5-4a19-96ea-47689a4feab4.sql", "ALTER TABLE public.applications ADD COLUMN IF NOT EXISTS startklar_ab date;"], ["20260828163542_c2b38440-6fc0-4202-b2cd-2da8728704f8.sql", "ALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS internal_interviews boolean NOT NULL DEFAULT false;\n\nCREATE OR REPLACE FUNCTION public.has_internal_interviews()\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.user_id = auth.uid() AND e.internal_interviews = true\n  )\n$$;\n\n-- interview_appointments\nDROP POLICY IF EXISTS \"Internal interviewers can view interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Internal interviewers can view interview appointments\"\nON public.interview_appointments FOR SELECT TO authenticated\nUSING (public.has_internal_interviews());\n\nDROP POLICY IF EXISTS \"Internal interviewers can update interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Internal interviewers can update interview appointments\"\nON public.interview_appointments FOR UPDATE TO authenticated\nUSING (public.has_internal_interviews())\nWITH CHECK (public.has_internal_interviews());\n\n-- applications\nDROP POLICY IF EXISTS \"Internal interviewers can view applications\" ON public.applications;\nCREATE POLICY \"Internal interviewers can view applications\"\nON public.applications FOR SELECT TO authenticated\nUSING (public.has_internal_interviews());\n\nDROP POLICY IF EXISTS \"Internal interviewers can update applications\" ON public.applications;\nCREATE POLICY \"Internal interviewers can update applications\"\nON public.applications FOR UPDATE TO authenticated\nUSING (public.has_internal_interviews())\nWITH CHECK (public.has_internal_interviews());\n\n-- Lebenslauf-Dateien\nDROP POLICY IF EXISTS \"Internal interviewers can read application files\" ON storage.objects;\nCREATE POLICY \"Internal interviewers can read application files\"\nON storage.objects FOR SELECT TO authenticated\nUSING (bucket_id = 'applications' AND public.has_internal_interviews());\n\nUPDATE public.interview_appointments SET status = 'mailbox' WHERE status = 'abgesagt';"], ["20260828170143_7b1fde01-1399-4b47-a4b7-7ceaa0ed5896.sql", "ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS internal_interviews_since timestamptz;\n\nCREATE OR REPLACE FUNCTION public.employees_track_internal_interviews()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.internal_interviews THEN\n      NEW.internal_interviews_since := now();\n    ELSE\n      NEW.internal_interviews_since := NULL;\n    END IF;\n  ELSE\n    IF NEW.internal_interviews AND NOT COALESCE(OLD.internal_interviews, false) THEN\n      NEW.internal_interviews_since := now();\n    ELSIF NOT NEW.internal_interviews THEN\n      NEW.internal_interviews_since := NULL;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS employees_track_internal_interviews ON public.employees;\nCREATE TRIGGER employees_track_internal_interviews\nBEFORE INSERT OR UPDATE ON public.employees\nFOR EACH ROW EXECUTE FUNCTION public.employees_track_internal_interviews();\n\nUPDATE public.employees\nSET internal_interviews_since = now()\nWHERE internal_interviews = true AND internal_interviews_since IS NULL;\n\nCREATE OR REPLACE FUNCTION public.internal_interviews_since()\nRETURNS timestamptz\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT e.internal_interviews_since\n  FROM public.employees e\n  WHERE e.user_id = auth.uid() AND e.internal_interviews = true\n  ORDER BY e.internal_interviews_since NULLS LAST\n  LIMIT 1\n$$;\n\nDROP POLICY IF EXISTS \"Internal interviewers can view interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Internal interviewers can view interview appointments\"\nON public.interview_appointments FOR SELECT TO authenticated\nUSING (\n  public.has_internal_interviews()\n  AND booked_at >= public.internal_interviews_since()\n);\n\nDROP POLICY IF EXISTS \"Internal interviewers can update interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Internal interviewers can update interview appointments\"\nON public.interview_appointments FOR UPDATE TO authenticated\nUSING (\n  public.has_internal_interviews()\n  AND booked_at >= public.internal_interviews_since()\n)\nWITH CHECK (\n  public.has_internal_interviews()\n  AND booked_at >= public.internal_interviews_since()\n);\n\nDROP POLICY IF EXISTS \"Internal interviewers can view applications\" ON public.applications;\nCREATE POLICY \"Internal interviewers can view applications\"\nON public.applications FOR SELECT TO authenticated\nUSING (\n  public.has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ia.booked_at >= public.internal_interviews_since()\n  )\n);\n\nDROP POLICY IF EXISTS \"Internal interviewers can update applications\" ON public.applications;\nCREATE POLICY \"Internal interviewers can update applications\"\nON public.applications FOR UPDATE TO authenticated\nUSING (\n  public.has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ia.booked_at >= public.internal_interviews_since()\n  )\n)\nWITH CHECK (\n  public.has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ia.booked_at >= public.internal_interviews_since()\n  )\n);"], ["20260828171104_1078be9e-e66a-4435-9444-0f06676c8a97.sql", "DROP POLICY IF EXISTS \"Internal interviewers can view interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Internal interviewers can view interview appointments\"\nON public.interview_appointments FOR SELECT\nUSING (\n  has_internal_interviews()\n  AND ((appointment_date + appointment_time) AT TIME ZONE 'Europe/Berlin') >= internal_interviews_since()\n);\n\nDROP POLICY IF EXISTS \"Internal interviewers can update interview appointments\" ON public.interview_appointments;\nCREATE POLICY \"Internal interviewers can update interview appointments\"\nON public.interview_appointments FOR UPDATE\nUSING (\n  has_internal_interviews()\n  AND ((appointment_date + appointment_time) AT TIME ZONE 'Europe/Berlin') >= internal_interviews_since()\n);\n\nDROP POLICY IF EXISTS \"Internal interviewers can view applications\" ON public.applications;\nCREATE POLICY \"Internal interviewers can view applications\"\nON public.applications FOR SELECT\nUSING (\n  has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ((ia.appointment_date + ia.appointment_time) AT TIME ZONE 'Europe/Berlin') >= internal_interviews_since()\n  )\n);\n\nDROP POLICY IF EXISTS \"Internal interviewers can update applications\" ON public.applications;\nCREATE POLICY \"Internal interviewers can update applications\"\nON public.applications FOR UPDATE\nUSING (\n  has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ((ia.appointment_date + ia.appointment_time) AT TIME ZONE 'Europe/Berlin') >= internal_interviews_since()\n  )\n);"], ["20260831084536_e538da1a-e189-4774-83b2-6296e1d3922b.sql", "CREATE TABLE public.short_links (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  code text NOT NULL UNIQUE,\n  target_url text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT ON public.short_links TO anon;\nGRANT SELECT ON public.short_links TO authenticated;\nGRANT ALL ON public.short_links TO service_role;\n\nALTER TABLE public.short_links ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"short_links_public_select\"\nON public.short_links FOR SELECT\nUSING (true);\n\nCREATE POLICY \"short_links_superadmin_insert\"\nON public.short_links FOR INSERT\nTO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TABLE public.sms_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  application_id uuid REFERENCES public.applications(id) ON DELETE SET NULL,\n  recipient text NOT NULL,\n  normalized_recipient text,\n  message text NOT NULL,\n  status text NOT NULL DEFAULT 'sent',\n  error text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT ON public.sms_logs TO authenticated;\nGRANT ALL ON public.sms_logs TO service_role;\n\nALTER TABLE public.sms_logs ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"sms_logs_superadmin_select\"\nON public.sms_logs FOR SELECT\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS sms_enabled boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS seven_api_key text,\n  ADD COLUMN IF NOT EXISTS sms_sender_name text,\n  ADD COLUMN IF NOT EXISTS sms_interview_text text DEFAULT 'Hallo {vorname}, danke fuer deine Bewerbung bei {unternehmen}. Buche dein Bewerbungsgespraech hier: {link}';"], ["20260831091541_101ea3a1-f56a-4a54-ab81-ebf94ff49e2c.sql", "ALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS sms_confirmation_text text DEFAULT 'Hallo {vorname}, dein Bewerbungsgespr\u00e4ch bei {unternehmen} ist best\u00e4tigt: {datum} um {uhrzeit} Uhr. Bis dann!',\n  ADD COLUMN IF NOT EXISTS sms_reminder_text text DEFAULT 'Hallo {vorname}, Erinnerung: dein Bewerbungsgespr\u00e4ch bei {unternehmen} startet um {uhrzeit} Uhr.';\n\nUPDATE public.app_settings\n  SET sms_confirmation_text = COALESCE(sms_confirmation_text, 'Hallo {vorname}, dein Bewerbungsgespr\u00e4ch bei {unternehmen} ist best\u00e4tigt: {datum} um {uhrzeit} Uhr. Bis dann!'),\n      sms_reminder_text = COALESCE(sms_reminder_text, 'Hallo {vorname}, Erinnerung: dein Bewerbungsgespr\u00e4ch bei {unternehmen} startet um {uhrzeit} Uhr.');\n\nALTER TABLE public.interview_appointments\n  ADD COLUMN IF NOT EXISTS sms_reminder_sent_at timestamp with time zone;"], ["20260907082704_e38de466-4a95-4527-8f0c-8192ed212146.sql", "-- 1. Rollen-Enum\nCREATE TYPE public.app_role AS ENUM ('superadmin', 'kunde', 'mitarbeiter');\n\nCREATE TABLE public.profiles (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name TEXT,\n  company TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;\nGRANT ALL ON public.profiles TO service_role;\n\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\n\nCREATE TABLE public.user_roles (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  role public.app_role NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (user_id, role)\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated;\nGRANT ALL ON public.user_roles TO service_role;\n\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role public.app_role)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$$;\n\nCREATE POLICY \"Users can view own profile\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update own profile\"\n  ON public.profiles FOR UPDATE\n  TO authenticated\n  USING (auth.uid() = user_id)\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can insert own profile\"\n  ON public.profiles FOR INSERT\n  TO authenticated\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Superadmins can view all profiles\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can update all profiles\"\n  ON public.profiles FOR UPDATE\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Users can view own roles\"\n  ON public.user_roles FOR SELECT\n  TO authenticated\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Superadmins can view all roles\"\n  ON public.user_roles FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can manage all roles\"\n  ON public.user_roles FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER update_profiles_updated_at\n  BEFORE UPDATE ON public.profiles\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _requested_role public.app_role;\nBEGIN\n  INSERT INTO public.profiles (user_id, full_name, company)\n  VALUES (\n    NEW.id,\n    NEW.raw_user_meta_data->>'full_name',\n    NEW.raw_user_meta_data->>'company'\n  );\n\n  _requested_role := CASE\n    WHEN NEW.raw_user_meta_data->>'role' IN ('kunde', 'mitarbeiter')\n      THEN (NEW.raw_user_meta_data->>'role')::public.app_role\n    ELSE 'kunde'::public.app_role\n  END;\n\n  INSERT INTO public.user_roles (user_id, role)\n  VALUES (NEW.id, _requested_role);\n\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();\n\nCREATE TABLE public.clients (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_name text,\n  website text,\n  company_description text,\n  industry text,\n  contact_person text,\n  street text,\n  postal_code text,\n  city text,\n  vat_id text,\n  phone text,\n  email text,\n  contact_phone text,\n  contact_email text,\n  logo_url text,\n  greeting_text text,\n  forwarding_enabled boolean NOT NULL DEFAULT false,\n  is_draft boolean NOT NULL DEFAULT false,\n  sip_phone_number text,\n  sip_server text,\n  sip_username text,\n  sip_password text,\n  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.clients TO authenticated;\nGRANT ALL ON public.clients TO service_role;\n\nALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can manage all clients\"\n  ON public.clients\n  FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_clients_updated_at\n  BEFORE UPDATE ON public.clients\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE POLICY \"Public read for client-logos\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'client-logos');\n\nCREATE POLICY \"Superadmins can upload client-logos\"\n  ON storage.objects FOR INSERT\n  TO authenticated\n  WITH CHECK (bucket_id = 'client-logos' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can update client-logos\"\n  ON storage.objects FOR UPDATE\n  TO authenticated\n  USING (bucket_id = 'client-logos' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can delete client-logos\"\n  ON storage.objects FOR DELETE\n  TO authenticated\n  USING (bucket_id = 'client-logos' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TABLE public.employees (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid,\n  first_name text,\n  last_name text,\n  personal_email text,\n  personal_phone text,\n  login_local_part text,\n  login_email text,\n  password_plain text,\n  contract_type text CHECK (contract_type IN ('vollzeit','teilzeit')),\n  start_date date,\n  salary numeric(10,2),\n  birth_date date,\n  birth_place text,\n  nationality text,\n  marital_status text,\n  iban text,\n  bic text,\n  bank_name text,\n  tax_id text,\n  social_security_number text,\n  health_insurance text,\n  is_draft boolean NOT NULL DEFAULT true,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE UNIQUE INDEX employees_login_email_active_uniq\n  ON public.employees (login_email)\n  WHERE is_draft = false AND login_email IS NOT NULL;\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.employees TO authenticated;\nGRANT ALL ON public.employees TO service_role;\n\nALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can manage all employees\"\n  ON public.employees\n  FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'::public.app_role))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'::public.app_role));\n\nCREATE TRIGGER employees_set_updated_at\n  BEFORE UPDATE ON public.employees\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TABLE public.assignments (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,\n  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (employee_id, client_id)\n);\n\nCREATE INDEX assignments_employee_id_idx ON public.assignments(employee_id);\nCREATE INDEX assignments_client_id_idx ON public.assignments(client_id);\n\nGRANT SELECT, INSERT, DELETE ON public.assignments TO authenticated;\nGRANT ALL ON public.assignments TO service_role;\n\nALTER TABLE public.assignments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view assignments\"\n  ON public.assignments FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can create assignments\"\n  ON public.assignments FOR INSERT\n  TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin') AND created_by = auth.uid());\n\nCREATE POLICY \"Superadmins can delete assignments\"\n  ON public.assignments FOR DELETE\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));"], ["20260907082933_039222ff-b838-4e27-a465-996b3d8fb4a2.sql", "CREATE TABLE public.contract_templates (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  title text NOT NULL,\n  category text,\n  monthly_salary numeric(10,2) NOT NULL DEFAULT 0,\n  content_html text NOT NULL DEFAULT '',\n  version integer NOT NULL DEFAULT 1,\n  is_active boolean NOT NULL DEFAULT true,\n  created_by uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.contract_templates TO authenticated;\nGRANT ALL ON public.contract_templates TO service_role;\n\nALTER TABLE public.contract_templates ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage contract templates\"\n  ON public.contract_templates FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER trg_contract_templates_updated_at\n  BEFORE UPDATE ON public.contract_templates\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TABLE public.company_signature (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  singleton boolean NOT NULL DEFAULT true UNIQUE,\n  signer_name text NOT NULL DEFAULT '',\n  signer_title text NOT NULL DEFAULT '',\n  signature_url text,\n  signature_source text NOT NULL DEFAULT 'generated' CHECK (signature_source IN ('generated','uploaded')),\n  signature_style text CHECK (signature_style IN ('elegant','professional','cursive','bold')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.company_signature TO authenticated;\nGRANT ALL ON public.company_signature TO service_role;\n\nALTER TABLE public.company_signature ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage company signature\"\n  ON public.company_signature FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER trg_company_signature_updated_at\n  BEFORE UPDATE ON public.company_signature\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE POLICY \"Superadmins read contract-assets\"\n  ON storage.objects FOR SELECT TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE POLICY \"Superadmins insert contract-assets\"\n  ON storage.objects FOR INSERT TO authenticated\n  WITH CHECK (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE POLICY \"Superadmins update contract-assets\"\n  ON storage.objects FOR UPDATE TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE POLICY \"Superadmins delete contract-assets\"\n  ON storage.objects FOR DELETE TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(),'superadmin'));\n\nCREATE OR REPLACE FUNCTION public.is_client_assigned_to_me(_client_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.assignments a\n    JOIN public.employees e ON e.id = a.employee_id\n    WHERE a.client_id = _client_id\n      AND e.user_id = auth.uid()\n  )\n$$;\n\nCREATE POLICY \"Employees can view assigned clients\"\nON public.clients\nFOR SELECT\nTO authenticated\nUSING (public.is_client_assigned_to_me(id));\n\nCREATE POLICY \"Employees can view own assignments\"\nON public.assignments\nFOR SELECT\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = assignments.employee_id\n      AND e.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Employees can view own record\"\nON public.employees\nFOR SELECT\nTO authenticated\nUSING (user_id = auth.uid());\n\nALTER TABLE public.clients\n  DROP COLUMN IF EXISTS sip_phone_number,\n  DROP COLUMN IF EXISTS sip_server,\n  DROP COLUMN IF EXISTS sip_username,\n  DROP COLUMN IF EXISTS sip_password;\n\nCREATE TABLE public.client_phone_numbers (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  phone_number TEXT NOT NULL,\n  label TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (phone_number)\n);\nCREATE INDEX client_phone_numbers_client_idx ON public.client_phone_numbers(client_id);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.client_phone_numbers TO authenticated;\nGRANT ALL ON public.client_phone_numbers TO service_role;\n\nALTER TABLE public.client_phone_numbers ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin manages phone numbers\"\nON public.client_phone_numbers FOR ALL\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees read numbers of assigned clients\"\nON public.client_phone_numbers FOR SELECT\nTO authenticated\nUSING (public.is_client_assigned_to_me(client_id));\n\nCREATE TRIGGER trg_client_phone_numbers_updated_at\nBEFORE UPDATE ON public.client_phone_numbers\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TABLE public.sipgate_calls (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  sipgate_call_id TEXT NOT NULL UNIQUE,\n  direction TEXT NOT NULL CHECK (direction IN ('in','out')),\n  from_number TEXT,\n  to_number TEXT,\n  client_id UUID REFERENCES public.clients(id) ON DELETE SET NULL,\n  answered_by_employee_id UUID REFERENCES public.employees(id) ON DELETE SET NULL,\n  handled_by_employee_id UUID REFERENCES public.employees(id) ON DELETE SET NULL,\n  status TEXT NOT NULL DEFAULT 'ringing' CHECK (status IN ('ringing','answered','missed','ended')),\n  caller_name TEXT,\n  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  answered_at TIMESTAMPTZ,\n  ended_at TIMESTAMPTZ,\n  raw_payload JSONB,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX sipgate_calls_client_idx ON public.sipgate_calls(client_id);\nCREATE INDEX sipgate_calls_status_idx ON public.sipgate_calls(status);\nCREATE INDEX sipgate_calls_started_at_idx ON public.sipgate_calls(started_at DESC);\n\nGRANT SELECT, UPDATE ON public.sipgate_calls TO authenticated;\nGRANT ALL ON public.sipgate_calls TO service_role;\n\nALTER TABLE public.sipgate_calls ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin reads all calls\"\nON public.sipgate_calls FOR SELECT\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees read calls of assigned clients\"\nON public.sipgate_calls FOR SELECT\nTO authenticated\nUSING (\n  client_id IS NOT NULL\n  AND public.is_client_assigned_to_me(client_id)\n);\n\nCREATE POLICY \"Employees claim assigned calls\"\nON public.sipgate_calls FOR UPDATE\nTO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR (client_id IS NOT NULL AND public.is_client_assigned_to_me(client_id))\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR (client_id IS NOT NULL AND public.is_client_assigned_to_me(client_id))\n);\n\nCREATE TRIGGER trg_sipgate_calls_updated_at\nBEFORE UPDATE ON public.sipgate_calls\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nALTER PUBLICATION supabase_realtime ADD TABLE public.sipgate_calls;\nALTER TABLE public.sipgate_calls REPLICA IDENTITY FULL;\n\nALTER TABLE public.employees ADD COLUMN IF NOT EXISTS sipgate_user_id TEXT;\nCREATE INDEX IF NOT EXISTS employees_sipgate_user_id_idx ON public.employees(sipgate_user_id);"], ["20260907083017_37e7871b-271d-4bd8-b740-605c6094498d.sql", "CREATE TYPE public.employee_contract_status AS ENUM ('pending_employee', 'pending_admin', 'completed');\n\nCREATE TABLE public.employee_contracts (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL UNIQUE REFERENCES public.employees(id) ON DELETE CASCADE,\n  template_id uuid NOT NULL REFERENCES public.contract_templates(id) ON DELETE RESTRICT,\n  status public.employee_contract_status NOT NULL DEFAULT 'pending_employee',\n  employee_signature_data_url text,\n  signed_at timestamptz,\n  admin_confirmed_at timestamptz,\n  admin_confirmed_by uuid,\n  pdf_path text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.employee_contracts TO authenticated;\nGRANT ALL ON public.employee_contracts TO service_role;\n\nALTER TABLE public.employee_contracts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage all employee contracts\"\n  ON public.employee_contracts FOR ALL\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees can view their own contract\"\n  ON public.employee_contracts FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.employees e\n      WHERE e.id = employee_contracts.employee_id AND e.user_id = auth.uid()\n    )\n  );\n\nCREATE POLICY \"Employees can update their own contract\"\n  ON public.employee_contracts FOR UPDATE\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.employees e\n      WHERE e.id = employee_contracts.employee_id AND e.user_id = auth.uid()\n    )\n    AND status = 'pending_employee'\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM public.employees e\n      WHERE e.id = employee_contracts.employee_id AND e.user_id = auth.uid()\n    )\n    AND status IN ('pending_employee', 'pending_admin')\n  );\n\nCREATE TRIGGER update_employee_contracts_updated_at\n  BEFORE UPDATE ON public.employee_contracts\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE POLICY \"Employees can update their own employee row\"\n  ON public.employees FOR UPDATE\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\nCREATE POLICY \"Employees can read their own contract PDF\"\n  ON storage.objects FOR SELECT\n  TO authenticated\n  USING (\n    bucket_id = 'contract-assets'\n    AND EXISTS (\n      SELECT 1\n      FROM public.employee_contracts ec\n      JOIN public.employees e ON e.id = ec.employee_id\n      WHERE e.user_id = auth.uid()\n        AND ec.pdf_path = storage.objects.name\n    )\n  );\n\nCREATE POLICY \"Superadmins manage contract-assets\"\n  ON storage.objects FOR ALL\n  TO authenticated\n  USING (bucket_id = 'contract-assets' AND public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (bucket_id = 'contract-assets' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees can read their assigned template\"\n  ON public.contract_templates\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM public.employee_contracts ec\n      JOIN public.employees e ON e.id = ec.employee_id\n      WHERE ec.template_id = contract_templates.id\n        AND e.user_id = auth.uid()\n    )\n  );\n\nCREATE TABLE public.call_notes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,\n  sipgate_call_id uuid REFERENCES public.sipgate_calls(id) ON DELETE SET NULL,\n  anrufer_name text,\n  anrufer_nummer text,\n  anrufer_email text,\n  anliegen text NOT NULL,\n  kategorie text,\n  prioritaet text NOT NULL DEFAULT 'normal',\n  weitergeleitet_an text,\n  rueckruf_gewuenscht boolean NOT NULL DEFAULT false,\n  rueckruf_zeit text,\n  dauer_sekunden integer NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.call_notes TO authenticated;\nGRANT ALL ON public.call_notes TO service_role;\n\nALTER TABLE public.call_notes ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Employee reads own notes\" ON public.call_notes\nFOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Superadmin reads all notes\" ON public.call_notes\nFOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employee inserts own notes\" ON public.call_notes\nFOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n  AND public.is_client_assigned_to_me(call_notes.client_id)\n);\n\nCREATE POLICY \"Superadmin inserts notes\" ON public.call_notes\nFOR INSERT TO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employee updates own notes\" ON public.call_notes\nFOR UPDATE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Superadmin updates notes\" ON public.call_notes\nFOR UPDATE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employee deletes own notes\" ON public.call_notes\nFOR DELETE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = call_notes.employee_id AND e.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Superadmin deletes notes\" ON public.call_notes\nFOR DELETE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_call_notes_updated_at\nBEFORE UPDATE ON public.call_notes\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE INDEX call_notes_employee_created_idx ON public.call_notes (employee_id, created_at DESC);\nCREATE INDEX call_notes_client_idx ON public.call_notes (client_id);"], ["20260907083053_c72c8c2b-467d-4844-ad52-e068cbe0fa1a.sql", "CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA extensions;\nCREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;\n\nCREATE TABLE public.caller_contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,\n  phone_number text NOT NULL,\n  caller_name text,\n  caller_email text,\n  last_seen_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (client_id, phone_number)\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.caller_contacts TO authenticated;\nGRANT ALL ON public.caller_contacts TO service_role;\n\nALTER TABLE public.caller_contacts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins full access to caller_contacts\"\nON public.caller_contacts FOR ALL\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Mitarbeiter can view assigned caller_contacts\"\nON public.caller_contacts FOR SELECT\nTO authenticated\nUSING (public.is_client_assigned_to_me(client_id));\n\nCREATE POLICY \"Mitarbeiter can insert assigned caller_contacts\"\nON public.caller_contacts FOR INSERT\nTO authenticated\nWITH CHECK (public.is_client_assigned_to_me(client_id));\n\nCREATE POLICY \"Mitarbeiter can update assigned caller_contacts\"\nON public.caller_contacts FOR UPDATE\nTO authenticated\nUSING (public.is_client_assigned_to_me(client_id))\nWITH CHECK (public.is_client_assigned_to_me(client_id));\n\nCREATE INDEX idx_caller_contacts_lookup ON public.caller_contacts(client_id, phone_number);\n\nCREATE TRIGGER update_caller_contacts_updated_at\nBEFORE UPDATE ON public.caller_contacts\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TABLE public.applications (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  vorname TEXT NOT NULL,\n  nachname TEXT NOT NULL,\n  email TEXT NOT NULL,\n  handynummer TEXT NOT NULL,\n  geburtsdatum DATE NOT NULL,\n  staatsangehoerigkeit TEXT NOT NULL,\n  anstellung TEXT NOT NULL,\n  lebenslauf_path TEXT,\n  lebenslauf_filename TEXT,\n  lebenslauf_mime TEXT,\n  status TEXT NOT NULL DEFAULT 'neu',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, UPDATE, DELETE ON public.applications TO authenticated;\nGRANT ALL ON public.applications TO service_role;\n\nALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin can view applications\"\n  ON public.applications FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can update applications\"\n  ON public.applications FOR UPDATE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can delete applications\"\n  ON public.applications FOR DELETE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_applications_updated_at\n  BEFORE UPDATE ON public.applications\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nALTER PUBLICATION supabase_realtime ADD TABLE public.applications;\n\nCREATE POLICY \"Superadmin can read application files\"\n  ON storage.objects FOR SELECT TO authenticated\n  USING (bucket_id = 'applications' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can delete application files\"\n  ON storage.objects FOR DELETE TO authenticated\n  USING (bucket_id = 'applications' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TABLE public.app_settings (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  singleton boolean NOT NULL DEFAULT true UNIQUE,\n  company_name text,\n  company_address text,\n  vat_id text,\n  accent_color text DEFAULT '#7bed9f',\n  logo_text text DEFAULT 'Sekreteriat24',\n  resend_api_key text,\n  resend_from_name text,\n  resend_from_email text,\n  application_email_enabled boolean NOT NULL DEFAULT false,\n  application_email_subject text DEFAULT 'Deine Bewerbung bei Sekreteriat24',\n  application_email_body text DEFAULT 'Hallo {{vorname}},\n\nvielen Dank f\u00fcr deine Bewerbung. Wir haben deine Unterlagen erhalten und melden uns in K\u00fcrze.\n\nViele Gr\u00fc\u00dfe\nSekreteriat24',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE ON public.app_settings TO authenticated;\nGRANT ALL ON public.app_settings TO service_role;\n\nALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmin can read settings\" ON public.app_settings\n  FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can insert settings\" ON public.app_settings\n  FOR INSERT TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmin can update settings\" ON public.app_settings\n  FOR UPDATE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_app_settings_updated_at\n  BEFORE UPDATE ON public.app_settings\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nINSERT INTO public.app_settings (singleton, company_name, company_address, vat_id)\nVALUES (true, 'Sekreteriat24 GmbH', 'Musterstra\u00dfe 12, 10115 Berlin', 'DE123456789')\nON CONFLICT (singleton) DO NOTHING;"], ["20260907083138_d73b3687-d59e-41d3-a811-5358b7ed3410.sql", "UPDATE public.app_settings\nSET\n  company_name = REPLACE(company_name, 'Sekreteriat', 'Sekretariat'),\n  logo_text = REPLACE(logo_text, 'Sekreteriat', 'Sekretariat'),\n  application_email_subject = REPLACE(application_email_subject, 'Sekreteriat', 'Sekretariat'),\n  application_email_body = REPLACE(application_email_body, 'Sekreteriat', 'Sekretariat');\n\nALTER TABLE public.app_settings\n  ALTER COLUMN logo_text SET DEFAULT 'Sekretariat24',\n  ALTER COLUMN application_email_subject SET DEFAULT 'Deine Bewerbung bei Sekretariat24',\n  ALTER COLUMN application_email_body SET DEFAULT E'Hallo {{vorname}} {{nachname}},\\n\\nvielen Dank f\u00fcr deine Bewerbung bei Sekretariat24.\\n\\nWir haben deine Unterlagen erhalten und pr\u00fcfen sie sorgf\u00e4ltig. In K\u00fcrze melden wir uns pers\u00f6nlich bei dir zur\u00fcck.\\n\\nMit freundlichen Gr\u00fc\u00dfen\\nDein Team von Sekretariat24';\n\nALTER TABLE public.applications ADD COLUMN IF NOT EXISTS ranking text;\nALTER TABLE public.applications ADD COLUMN IF NOT EXISTS booking_token uuid UNIQUE;\n\nALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS interview_email_enabled boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS interview_email_subject text DEFAULT 'Buche dein Bewerbungsgespr\u00e4ch bei Sekretariat24',\n  ADD COLUMN IF NOT EXISTS interview_email_body text DEFAULT E'Hallo {{vorname}},\\n\\nwir freuen uns \u00fcber deine Bewerbung und w\u00fcrden dich gerne pers\u00f6nlich kennenlernen.\\n\\nBitte w\u00e4hle \u00fcber den folgenden Link einen f\u00fcr dich passenden Termin f\u00fcr dein Bewerbungsgespr\u00e4ch:\\n\\n{{booking_url}}\\n\\nWir freuen uns auf das Gespr\u00e4ch!\\n\\nViele Gr\u00fc\u00dfe\\nDein Sekretariat24-Team',\n  ADD COLUMN IF NOT EXISTS interview_slot_start time NOT NULL DEFAULT '09:00',\n  ADD COLUMN IF NOT EXISTS interview_slot_end time NOT NULL DEFAULT '18:00',\n  ADD COLUMN IF NOT EXISTS interview_slot_interval_minutes int NOT NULL DEFAULT 30,\n  ADD COLUMN IF NOT EXISTS interview_available_weekdays int[] NOT NULL DEFAULT ARRAY[1,2,3,4,5];\n\nCREATE TABLE IF NOT EXISTS public.interview_appointments (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  application_id uuid NOT NULL UNIQUE REFERENCES public.applications(id) ON DELETE CASCADE,\n  appointment_date date NOT NULL,\n  appointment_time time NOT NULL,\n  status text NOT NULL DEFAULT 'neu',\n  notes text,\n  booked_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_interview_appointments_date\n  ON public.interview_appointments (appointment_date, appointment_time);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.interview_appointments TO authenticated;\nGRANT ALL ON public.interview_appointments TO service_role;\n\nALTER TABLE public.interview_appointments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage interview appointments\"\n  ON public.interview_appointments\n  FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER interview_appointments_updated_at\n  BEFORE UPDATE ON public.interview_appointments\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE OR REPLACE FUNCTION public.get_interview_by_token(_token uuid)\nRETURNS TABLE (\n  application_id uuid,\n  vorname text,\n  nachname text,\n  appointment_date date,\n  appointment_time time,\n  status text\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT a.id, a.vorname, a.nachname,\n         ia.appointment_date, ia.appointment_time, ia.status\n  FROM public.applications a\n  LEFT JOIN public.interview_appointments ia ON ia.application_id = a.id\n  WHERE a.booking_token = _token\n  LIMIT 1;\n$$;\n\nCREATE OR REPLACE FUNCTION public.list_booked_interview_slots()\nRETURNS TABLE (appointment_date date, appointment_time time)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT appointment_date, appointment_time\n  FROM public.interview_appointments\n  WHERE appointment_date >= CURRENT_DATE;\n$$;\n\nCREATE OR REPLACE FUNCTION public.book_interview_slot(\n  _token uuid,\n  _date date,\n  _time time\n) RETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _app_id uuid;\n  _appt_id uuid;\nBEGIN\n  SELECT id INTO _app_id FROM public.applications WHERE booking_token = _token;\n  IF _app_id IS NULL THEN\n    RAISE EXCEPTION 'invalid_token';\n  END IF;\n\n  IF _date < CURRENT_DATE THEN\n    RAISE EXCEPTION 'past_date';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.interview_appointments\n    WHERE appointment_date = _date\n      AND appointment_time = _time\n      AND application_id <> _app_id\n  ) THEN\n    RAISE EXCEPTION 'slot_taken';\n  END IF;\n\n  INSERT INTO public.interview_appointments (application_id, appointment_date, appointment_time, status, booked_at)\n  VALUES (_app_id, _date, _time, 'neu', now())\n  ON CONFLICT (application_id) DO UPDATE\n    SET appointment_date = EXCLUDED.appointment_date,\n        appointment_time = EXCLUDED.appointment_time,\n        status = 'neu',\n        booked_at = now(),\n        updated_at = now()\n  RETURNING id INTO _appt_id;\n\n  UPDATE public.applications\n    SET status = 'termin_gebucht', updated_at = now()\n    WHERE id = _app_id;\n\n  RETURN _appt_id;\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.get_interview_slot_config()\nRETURNS TABLE (\n  slot_start time,\n  slot_end time,\n  interval_minutes int,\n  weekdays int[],\n  company_name text,\n  accent_color text,\n  logo_text text\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT interview_slot_start, interview_slot_end, interview_slot_interval_minutes,\n         interview_available_weekdays, company_name, accent_color, logo_text\n  FROM public.app_settings\n  LIMIT 1;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_interview_by_token(uuid) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.list_booked_interview_slots() FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.book_interview_slot(uuid, date, time) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.get_interview_slot_config() FROM PUBLIC;\n\nGRANT EXECUTE ON FUNCTION public.get_interview_by_token(uuid) TO anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.list_booked_interview_slots() TO anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.book_interview_slot(uuid, date, time) TO anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.get_interview_slot_config() TO anon, authenticated;\n\nCREATE TABLE public.telegram_recipients (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  chat_id text NOT NULL UNIQUE,\n  label text,\n  is_active boolean NOT NULL DEFAULT true,\n  notify_applications boolean NOT NULL DEFAULT true,\n  notify_interviews boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.telegram_recipients TO authenticated;\nGRANT ALL ON public.telegram_recipients TO service_role;\n\nALTER TABLE public.telegram_recipients ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view telegram recipients\"\n  ON public.telegram_recipients FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can insert telegram recipients\"\n  ON public.telegram_recipients FOR INSERT TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can update telegram recipients\"\n  ON public.telegram_recipients FOR UPDATE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'))\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can delete telegram recipients\"\n  ON public.telegram_recipients FOR DELETE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_telegram_recipients_updated_at\n  BEFORE UPDATE ON public.telegram_recipients\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();"], ["20260907083226_d95a2327-91f4-4e88-b62d-601f0a93b5dc.sql", "CREATE TABLE public.activity_log (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  actor_user_id uuid NOT NULL,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text NOT NULL,\n  entity_id uuid,\n  details jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT ON public.activity_log TO authenticated;\nGRANT ALL ON public.activity_log TO service_role;\n\nALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view activity log\"\nON public.activity_log FOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can insert activity log\"\nON public.activity_log FOR INSERT TO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin') AND actor_user_id = auth.uid());\n\nCREATE INDEX activity_log_created_at_idx ON public.activity_log (created_at DESC);\n\nALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS confirmation_email_enabled boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS confirmation_email_subject text,\n  ADD COLUMN IF NOT EXISTS confirmation_email_body text;\n\nUPDATE public.app_settings\nSET confirmation_email_subject = COALESCE(confirmation_email_subject, 'Ihr Termin bei Sekretariat24 ist best\u00e4tigt'),\n    confirmation_email_body = COALESCE(confirmation_email_body,\n'Sehr geehrte/r {{voller_name}},\n\nvielen Dank f\u00fcr die Buchung Ihres Bewerbungsgespr\u00e4chs. Wir freuen uns sehr auf das pers\u00f6nliche Kennenlernen.\n\nIhr Termin ist hiermit verbindlich best\u00e4tigt. Sollten Sie den Termin nicht wahrnehmen k\u00f6nnen, geben Sie uns bitte rechtzeitig Bescheid.\n\nMit freundlichen Gr\u00fc\u00dfen\nIhr Team von Sekretariat24');\n\nCREATE TABLE public.managers (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL UNIQUE,\n  email text NOT NULL,\n  display_name text,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.managers TO authenticated;\nGRANT ALL ON public.managers TO service_role;\n\nALTER TABLE public.managers ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view managers\" ON public.managers\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'superadmin'));\nCREATE POLICY \"Superadmins can insert managers\" ON public.managers\nFOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\nCREATE POLICY \"Superadmins can update managers\" ON public.managers\nFOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\nCREATE POLICY \"Superadmins can delete managers\" ON public.managers\nFOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TRIGGER update_managers_updated_at\nBEFORE UPDATE ON public.managers\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE POLICY \"Managers can view interview appointments\" ON public.interview_appointments\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can update interview appointments\" ON public.interview_appointments\nFOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can delete interview appointments\" ON public.interview_appointments\nFOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view applications\" ON public.applications\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can update applications\" ON public.applications\nFOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view activity log\" ON public.activity_log\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\nCREATE POLICY \"Managers can insert activity log\" ON public.activity_log\nFOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'manager') AND actor_user_id = auth.uid());\n\nCREATE POLICY \"Managers can view app settings\" ON public.app_settings\nFOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can read application files\" ON storage.objects\nFOR SELECT TO authenticated USING (bucket_id = 'applications' AND public.has_role(auth.uid(), 'manager'));\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  _requested_role public.app_role;\nBEGIN\n  INSERT INTO public.profiles (user_id, full_name, company)\n  VALUES (\n    NEW.id,\n    NEW.raw_user_meta_data->>'full_name',\n    NEW.raw_user_meta_data->>'company'\n  );\n\n  _requested_role := CASE\n    WHEN NEW.raw_user_meta_data->>'role' IN ('kunde', 'mitarbeiter')\n      THEN (NEW.raw_user_meta_data->>'role')::public.app_role\n    ELSE 'kunde'::public.app_role\n  END;\n\n  INSERT INTO public.user_roles (user_id, role)\n  VALUES (NEW.id, _requested_role);\n\n  RETURN NEW;\nEND;\n$function$;\n\nALTER TABLE public.interview_appointments ADD COLUMN IF NOT EXISTS reminder_sent_at timestamptz;\nALTER TABLE public.interview_appointments\n  ADD COLUMN IF NOT EXISTS start_date date,\n  ADD COLUMN IF NOT EXISTS start_asap boolean NOT NULL DEFAULT false;"], ["20260907083308_43c8ec86-53c2-4752-8d58-7eb83f5a76f7.sql", "ALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS outbound_recruitment boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS caller_api_key text,\n  ADD COLUMN IF NOT EXISTS street text,\n  ADD COLUMN IF NOT EXISTS postal_code text,\n  ADD COLUMN IF NOT EXISTS city text,\n  ADD COLUMN IF NOT EXISTS onboarding_enabled boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS phone_system text,\n  ADD COLUMN IF NOT EXISTS softphone_email text,\n  ADD COLUMN IF NOT EXISTS softphone_password text;\n\nALTER TABLE public.employees\n  DROP CONSTRAINT IF EXISTS employees_phone_system_check;\n\nALTER TABLE public.employees\n  ADD CONSTRAINT employees_phone_system_check\n  CHECK (phone_system IS NULL OR phone_system IN ('sipgate','placetel'));\n\nALTER TABLE public.clients\n  ADD COLUMN IF NOT EXISTS is_recruitment boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS call_script_path text,\n  ADD COLUMN IF NOT EXISTS call_script_content text,\n  ADD COLUMN IF NOT EXISTS call_script_my_name text,\n  ADD COLUMN IF NOT EXISTS call_script_company_name text;\n\nCREATE POLICY \"Superadmin manages call scripts\"\nON storage.objects FOR ALL TO authenticated\nUSING (bucket_id = 'call-scripts' AND public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (bucket_id = 'call-scripts' AND public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Employees read assigned call scripts\"\nON storage.objects FOR SELECT TO authenticated\nUSING (\n  bucket_id = 'call-scripts'\n  AND EXISTS (\n    SELECT 1 FROM public.clients c\n    WHERE c.call_script_path = storage.objects.name\n      AND public.is_client_assigned_to_me(c.id)\n  )\n);\n\nALTER TABLE public.call_notes REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.call_notes;\n\nALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS welcome_email_enabled boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS welcome_email_subject text,\n  ADD COLUMN IF NOT EXISTS welcome_email_body text;\n\nUPDATE public.app_settings\nSET welcome_email_subject = COALESCE(welcome_email_subject, 'Deine Zugangsdaten f\u00fcr dein Mitarbeiterkonto'),\n    welcome_email_body = COALESCE(welcome_email_body, 'Hallo {{ vorname }},\n\nwillkommen im Team! Wir haben dein pers\u00f6nliches Mitarbeiterkonto f\u00fcr dich angelegt.\n\nUnten findest du deine Zugangsdaten. Bitte logge dich \u00fcber den Button ein und f\u00fclle im Anschluss deinen Arbeitsvertrag aus und unterschreibe ihn digital.\n\nBitte bewahre deine Zugangsdaten sicher auf und gib sie nicht an Dritte weiter.\n\nBei Fragen kannst du dich jederzeit bei uns melden.');\n\nALTER TABLE public.telegram_recipients ADD COLUMN IF NOT EXISTS notify_contracts boolean NOT NULL DEFAULT true;\n\nALTER TABLE public.applications ADD COLUMN IF NOT EXISTS stelle text;\n\nCREATE TABLE public.interview_blocked_slots (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  blocked_date date NOT NULL,\n  blocked_time time without time zone NOT NULL,\n  reason text,\n  created_by uuid,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE (blocked_date, blocked_time)\n);\n\nGRANT SELECT, INSERT, DELETE ON public.interview_blocked_slots TO authenticated;\nGRANT ALL ON public.interview_blocked_slots TO service_role;\n\nALTER TABLE public.interview_blocked_slots ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins can view blocked slots\"\n  ON public.interview_blocked_slots FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can create blocked slots\"\n  ON public.interview_blocked_slots FOR INSERT TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Superadmins can delete blocked slots\"\n  ON public.interview_blocked_slots FOR DELETE TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE OR REPLACE FUNCTION public.list_booked_interview_slots()\nRETURNS TABLE(appointment_date date, appointment_time time without time zone)\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\n  SELECT appointment_date, appointment_time\n  FROM public.interview_appointments\n  WHERE appointment_date >= CURRENT_DATE\n  UNION\n  SELECT blocked_date, blocked_time\n  FROM public.interview_blocked_slots\n  WHERE blocked_date >= CURRENT_DATE;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.book_interview_slot(_token uuid, _date date, _time time without time zone)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  _app_id uuid;\n  _appt_id uuid;\nBEGIN\n  SELECT id INTO _app_id FROM public.applications WHERE booking_token = _token;\n  IF _app_id IS NULL THEN\n    RAISE EXCEPTION 'invalid_token';\n  END IF;\n\n  IF _date < CURRENT_DATE THEN\n    RAISE EXCEPTION 'past_date';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.interview_blocked_slots\n    WHERE blocked_date = _date AND blocked_time = _time\n  ) THEN\n    RAISE EXCEPTION 'slot_blocked';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.interview_appointments\n    WHERE appointment_date = _date\n      AND appointment_time = _time\n      AND application_id <> _app_id\n  ) THEN\n    RAISE EXCEPTION 'slot_taken';\n  END IF;\n\n  INSERT INTO public.interview_appointments (application_id, appointment_date, appointment_time, status, booked_at)\n  VALUES (_app_id, _date, _time, 'neu', now())\n  ON CONFLICT (application_id) DO UPDATE\n    SET appointment_date = EXCLUDED.appointment_date,\n        appointment_time = EXCLUDED.appointment_time,\n        status = 'neu',\n        booked_at = now(),\n        updated_at = now()\n  RETURNING id INTO _appt_id;\n\n  UPDATE public.applications\n    SET status = 'termin_gebucht', updated_at = now()\n    WHERE id = _app_id;\n\n  RETURN _appt_id;\nEND;\n$function$;"], ["20260907083356_de919cee-d3cd-4265-8082-042d40b11f0b.sql", "CREATE TABLE public.chat_conversations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL UNIQUE REFERENCES public.employees(id) ON DELETE CASCADE,\n  last_message_at timestamptz,\n  employee_active_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_conversations TO authenticated;\nGRANT ALL ON public.chat_conversations TO service_role;\n\nALTER TABLE public.chat_conversations ENABLE ROW LEVEL SECURITY;\n\nCREATE OR REPLACE FUNCTION public.is_my_conversation(_conversation_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.chat_conversations c\n    JOIN public.employees e ON e.id = c.employee_id\n    WHERE c.id = _conversation_id\n      AND e.user_id = auth.uid()\n  )\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_my_employee_row(_employee_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.id = _employee_id AND e.user_id = auth.uid()\n  )\n$$;\n\nCREATE POLICY \"Staff can view own conversation\"\nON public.chat_conversations FOR SELECT TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n);\n\nCREATE POLICY \"Staff can create own conversation\"\nON public.chat_conversations FOR INSERT TO authenticated\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n);\n\nCREATE POLICY \"Staff can update own conversation\"\nON public.chat_conversations FOR UPDATE TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_employee_row(employee_id)\n);\n\nCREATE POLICY \"Admins can delete conversations\"\nON public.chat_conversations FOR DELETE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TABLE public.chat_messages (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  conversation_id uuid NOT NULL REFERENCES public.chat_conversations(id) ON DELETE CASCADE,\n  sender_role text NOT NULL CHECK (sender_role IN ('manager','mitarbeiter')),\n  sender_user_id uuid,\n  sent_as_superadmin boolean NOT NULL DEFAULT false,\n  content text NOT NULL DEFAULT '',\n  edited_at timestamptz,\n  deleted_at timestamptz,\n  read boolean NOT NULL DEFAULT false,\n  read_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX idx_chat_messages_conversation ON public.chat_messages(conversation_id, created_at);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_messages TO authenticated;\nGRANT ALL ON public.chat_messages TO service_role;\n\nALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Participants can view messages\"\nON public.chat_messages FOR SELECT TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_conversation(conversation_id)\n);\n\nCREATE POLICY \"Participants can send messages\"\nON public.chat_messages FOR INSERT TO authenticated\nWITH CHECK (\n  (\n    (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'))\n    AND sender_role = 'manager'\n  )\n  OR (\n    public.is_my_conversation(conversation_id)\n    AND sender_role = 'mitarbeiter'\n    AND sender_user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Participants can update messages\"\nON public.chat_messages FOR UPDATE TO authenticated\nUSING (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_conversation(conversation_id)\n)\nWITH CHECK (\n  public.has_role(auth.uid(), 'superadmin')\n  OR public.has_role(auth.uid(), 'manager')\n  OR public.is_my_conversation(conversation_id)\n);\n\nCREATE POLICY \"Admins can delete messages\"\nON public.chat_messages FOR DELETE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TABLE public.chat_agent_settings (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  singleton boolean NOT NULL DEFAULT true UNIQUE,\n  display_name text NOT NULL DEFAULT 'Daniel Schreiber',\n  status text NOT NULL DEFAULT 'online' CHECK (status IN ('online','away','offline')),\n  status_text text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE ON public.chat_agent_settings TO authenticated;\nGRANT ALL ON public.chat_agent_settings TO service_role;\n\nALTER TABLE public.chat_agent_settings ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Authenticated can read agent settings\"\nON public.chat_agent_settings FOR SELECT TO authenticated\nUSING (true);\n\nCREATE POLICY \"Admins can insert agent settings\"\nON public.chat_agent_settings FOR INSERT TO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Admins can update agent settings\"\nON public.chat_agent_settings FOR UPDATE TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'));\n\nINSERT INTO public.chat_agent_settings (singleton) VALUES (true);\n\nCREATE TRIGGER trg_chat_conversations_updated_at\nBEFORE UPDATE ON public.chat_conversations\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER trg_chat_messages_updated_at\nBEFORE UPDATE ON public.chat_messages\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER trg_chat_agent_settings_updated_at\nBEFORE UPDATE ON public.chat_agent_settings\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE OR REPLACE FUNCTION public.chat_touch_conversation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  UPDATE public.chat_conversations\n    SET last_message_at = NEW.created_at, updated_at = now()\n    WHERE id = NEW.conversation_id;\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER trg_chat_messages_touch\nAFTER INSERT ON public.chat_messages\nFOR EACH ROW EXECUTE FUNCTION public.chat_touch_conversation();\n\nALTER TABLE public.chat_messages REPLICA IDENTITY FULL;\nALTER TABLE public.chat_conversations REPLICA IDENTITY FULL;\nALTER TABLE public.chat_agent_settings REPLICA IDENTITY FULL;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_messages;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_conversations;\nALTER PUBLICATION supabase_realtime ADD TABLE public.chat_agent_settings;"], ["20260907083442_e08c9601-d501-4f13-a137-b0a95f0934d8.sql", "ALTER TABLE public.chat_agent_settings\n  DROP COLUMN IF EXISTS status_text,\n  ADD COLUMN IF NOT EXISTS online_from time NOT NULL DEFAULT '09:00',\n  ADD COLUMN IF NOT EXISTS offline_after time NOT NULL DEFAULT '18:00',\n  ADD COLUMN IF NOT EXISTS auto_offline boolean NOT NULL DEFAULT true;\n\nALTER TABLE public.telegram_recipients\n  ADD COLUMN IF NOT EXISTS notify_chat boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS notify_onboarding boolean NOT NULL DEFAULT true;\n\nCREATE TABLE public.onboarding_appointments (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  application_id uuid REFERENCES public.applications(id) ON DELETE SET NULL,\n  vorname text,\n  nachname text,\n  email text,\n  telefon text,\n  stelle text,\n  appointment_date date NOT NULL,\n  appointment_time time without time zone NOT NULL,\n  notes text,\n  status text NOT NULL DEFAULT 'offen',\n  reminder_sent_at timestamp with time zone,\n  start_date date,\n  created_by uuid,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.onboarding_appointments TO authenticated;\nGRANT ALL ON public.onboarding_appointments TO service_role;\n\nALTER TABLE public.onboarding_appointments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Superadmins manage onboarding appointments\"\nON public.onboarding_appointments FOR ALL TO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'))\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE POLICY \"Managers manage onboarding appointments\"\nON public.onboarding_appointments FOR ALL TO authenticated\nUSING (public.has_role(auth.uid(), 'manager'))\nWITH CHECK (public.has_role(auth.uid(), 'manager'));\n\nCREATE TRIGGER update_onboarding_appointments_updated_at\nBEFORE UPDATE ON public.onboarding_appointments\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE INDEX idx_onboarding_appointments_date ON public.onboarding_appointments (appointment_date);\n\nCREATE POLICY \"Managers can view employees\"\nON public.employees FOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'manager'));\n\nCREATE POLICY \"Managers can view employee contracts\"\nON public.employee_contracts FOR SELECT TO authenticated\nUSING (public.has_role(auth.uid(), 'manager'));\n\nALTER TABLE public.applications ADD COLUMN IF NOT EXISTS startklar_ab date;\n\nALTER TABLE public.employees\n  ADD COLUMN IF NOT EXISTS internal_interviews boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS internal_interviews_since timestamptz;\n\nCREATE OR REPLACE FUNCTION public.has_internal_interviews()\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.employees e\n    WHERE e.user_id = auth.uid() AND e.internal_interviews = true\n  )\n$$;\n\nCREATE OR REPLACE FUNCTION public.employees_track_internal_interviews()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.internal_interviews THEN\n      NEW.internal_interviews_since := now();\n    ELSE\n      NEW.internal_interviews_since := NULL;\n    END IF;\n  ELSE\n    IF NEW.internal_interviews AND NOT COALESCE(OLD.internal_interviews, false) THEN\n      NEW.internal_interviews_since := now();\n    ELSIF NOT NEW.internal_interviews THEN\n      NEW.internal_interviews_since := NULL;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS employees_track_internal_interviews ON public.employees;\nCREATE TRIGGER employees_track_internal_interviews\nBEFORE INSERT OR UPDATE ON public.employees\nFOR EACH ROW EXECUTE FUNCTION public.employees_track_internal_interviews();\n\nCREATE OR REPLACE FUNCTION public.internal_interviews_since()\nRETURNS timestamptz\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT e.internal_interviews_since\n  FROM public.employees e\n  WHERE e.user_id = auth.uid() AND e.internal_interviews = true\n  ORDER BY e.internal_interviews_since NULLS LAST\n  LIMIT 1\n$$;\n\nCREATE POLICY \"Internal interviewers can view interview appointments\"\nON public.interview_appointments FOR SELECT\nUSING (\n  public.has_internal_interviews()\n  AND ((appointment_date + appointment_time) AT TIME ZONE 'Europe/Berlin') >= public.internal_interviews_since()\n);\n\nCREATE POLICY \"Internal interviewers can update interview appointments\"\nON public.interview_appointments FOR UPDATE\nUSING (\n  public.has_internal_interviews()\n  AND ((appointment_date + appointment_time) AT TIME ZONE 'Europe/Berlin') >= public.internal_interviews_since()\n);\n\nCREATE POLICY \"Internal interviewers can view applications\"\nON public.applications FOR SELECT\nUSING (\n  public.has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ((ia.appointment_date + ia.appointment_time) AT TIME ZONE 'Europe/Berlin') >= public.internal_interviews_since()\n  )\n);\n\nCREATE POLICY \"Internal interviewers can update applications\"\nON public.applications FOR UPDATE\nUSING (\n  public.has_internal_interviews()\n  AND EXISTS (\n    SELECT 1 FROM public.interview_appointments ia\n    WHERE ia.application_id = applications.id\n      AND ((ia.appointment_date + ia.appointment_time) AT TIME ZONE 'Europe/Berlin') >= public.internal_interviews_since()\n  )\n);\n\nCREATE POLICY \"Internal interviewers can read application files\"\nON storage.objects FOR SELECT TO authenticated\nUSING (bucket_id = 'applications' AND public.has_internal_interviews());\n\nCREATE TABLE public.short_links (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  code text NOT NULL UNIQUE,\n  target_url text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT ON public.short_links TO anon;\nGRANT SELECT ON public.short_links TO authenticated;\nGRANT ALL ON public.short_links TO service_role;\n\nALTER TABLE public.short_links ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"short_links_public_select\"\nON public.short_links FOR SELECT\nUSING (true);\n\nCREATE POLICY \"short_links_superadmin_insert\"\nON public.short_links FOR INSERT\nTO authenticated\nWITH CHECK (public.has_role(auth.uid(), 'superadmin'));\n\nCREATE TABLE public.sms_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  application_id uuid REFERENCES public.applications(id) ON DELETE SET NULL,\n  recipient text NOT NULL,\n  normalized_recipient text,\n  message text NOT NULL,\n  status text NOT NULL DEFAULT 'sent',\n  error text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT ON public.sms_logs TO authenticated;\nGRANT ALL ON public.sms_logs TO service_role;\n\nALTER TABLE public.sms_logs ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"sms_logs_superadmin_select\"\nON public.sms_logs FOR SELECT\nTO authenticated\nUSING (public.has_role(auth.uid(), 'superadmin'));\n\nALTER TABLE public.app_settings\n  ADD COLUMN IF NOT EXISTS sms_enabled boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS seven_api_key text,\n  ADD COLUMN IF NOT EXISTS sms_sender_name text,\n  ADD COLUMN IF NOT EXISTS sms_interview_text text DEFAULT 'Hallo {vorname}, danke fuer deine Bewerbung bei {unternehmen}. Buche dein Bewerbungsgespraech hier: {link}',\n  ADD COLUMN IF NOT EXISTS sms_confirmation_text text DEFAULT 'Hallo {vorname}, dein Bewerbungsgespr\u00e4ch bei {unternehmen} ist best\u00e4tigt: {datum} um {uhrzeit} Uhr. Bis dann!',\n  ADD COLUMN IF NOT EXISTS sms_reminder_text text DEFAULT 'Hallo {vorname}, Erinnerung: dein Bewerbungsgespr\u00e4ch bei {unternehmen} startet um {uhrzeit} Uhr.';\n\nUPDATE public.app_settings\n  SET sms_confirmation_text = COALESCE(sms_confirmation_text, 'Hallo {vorname}, dein Bewerbungsgespr\u00e4ch bei {unternehmen} ist best\u00e4tigt: {datum} um {uhrzeit} Uhr. Bis dann!'),\n      sms_reminder_text = COALESCE(sms_reminder_text, 'Hallo {vorname}, Erinnerung: dein Bewerbungsgespr\u00e4ch bei {unternehmen} startet um {uhrzeit} Uhr.');\n\nALTER TABLE public.interview_appointments\n  ADD COLUMN IF NOT EXISTS sms_reminder_sent_at timestamp with time zone;"], ["20260908080952_b43ce846-73f9-42cf-abf2-6aac56625a5c.sql", "ALTER TABLE public.telegram_recipients ADD COLUMN IF NOT EXISTS notify_notes boolean NOT NULL DEFAULT true;"], ["20260909141324_e0cb83a4-5f76-434b-892b-b2f9bb67cfff.sql", "CREATE TABLE public.work_schedules (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL UNIQUE REFERENCES public.employees(id) ON DELETE CASCADE,\n  mode text NOT NULL DEFAULT 'uniform',\n  days jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.work_schedules TO authenticated;\nGRANT ALL ON public.work_schedules TO service_role;\n\nALTER TABLE public.work_schedules ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Employees manage own schedule\"\n  ON public.work_schedules FOR ALL TO authenticated\n  USING (public.is_my_employee_row(employee_id))\n  WITH CHECK (public.is_my_employee_row(employee_id));\n\nCREATE POLICY \"Admins view all schedules\"\n  ON public.work_schedules FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'));\n\nCREATE TRIGGER work_schedules_updated_at\n  BEFORE UPDATE ON public.work_schedules\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TABLE public.work_schedule_weeks (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,\n  week_start date NOT NULL,\n  days jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (employee_id, week_start)\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.work_schedule_weeks TO authenticated;\nGRANT ALL ON public.work_schedule_weeks TO service_role;\n\nALTER TABLE public.work_schedule_weeks ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Employees manage own schedule weeks\"\n  ON public.work_schedule_weeks FOR ALL TO authenticated\n  USING (public.is_my_employee_row(employee_id))\n  WITH CHECK (public.is_my_employee_row(employee_id));\n\nCREATE POLICY \"Admins view all schedule weeks\"\n  ON public.work_schedule_weeks FOR SELECT TO authenticated\n  USING (public.has_role(auth.uid(), 'superadmin') OR public.has_role(auth.uid(), 'manager'));\n\nCREATE TRIGGER work_schedule_weeks_updated_at\n  BEFORE UPDATE ON public.work_schedule_weeks\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE INDEX work_schedule_weeks_week_idx ON public.work_schedule_weeks (week_start);"]];
